script:
frappe.ui.form.on('Calibration Record', {
    refresh(frm) {
        schedule_submit_override(frm);
    },

    after_save(frm) {
        /*
         * Frappe rebuilds the primary action after saving.
         * Reapply our controlled Submit action afterward.
         */
        schedule_submit_override(frm);
    },

    custom_calibration_date(frm) {
        reset_interval_confirmation(frm);
        update_next_calibration_date(frm);
    },

    custom_calibration_interval_months(frm) {
        reset_interval_confirmation(frm);
        update_next_calibration_date(frm);
    }
});


function schedule_submit_override(frm) {
    setTimeout(function() {
        setup_calibration_submit_action(frm);
    }, 300);
}


function setup_calibration_submit_action(frm) {
    /*
     * Only replace the primary action when:
     * - the record is a draft;
     * - it has already been saved;
     * - there are no unsaved changes.
     */
    if (
        frm.doc.docstatus !== 0 ||
        frm.is_new() ||
        frm.is_dirty()
    ) {
        return;
    }

    frm.page.set_primary_action(
        __('Submit'),
        function() {
            show_calibration_interval_prompt(frm);
        }
    );
}


function show_calibration_interval_prompt(frm) {
    let dialog = new frappe.ui.Dialog({
        title: __('Confirm Next Calibration Period'),

        fields: [
            {
                label: __('Next Calibration Interval (Months)'),
                fieldname: 'interval_months',
                fieldtype: 'Int',
                default:
                    frm.doc.custom_calibration_interval_months ||
                    0,
                description: __(
                    'Enter 0 when calibration is on demand and no next calibration date is required.'
                ),
                reqd: 1
            }
        ],

        primary_action_label: __('Continue and Submit'),

        primary_action: async function(values) {
            let months = cint(
                values.interval_months || 0
            );

            if (months < 0) {
                frappe.msgprint(
                    __('Interval cannot be negative.')
                );
                return;
            }

            dialog.disable_primary_action();

            try {
                await frm.set_value(
                    'custom_calibration_interval_months',
                    months
                );

                await update_next_calibration_date(frm);

                await frm.set_value(
                    'custom_calibration_interval_confirmed',
                    1
                );

                /*
                 * Save the interval, calculated date and hidden
                 * confirmation checkbox.
                 */
                if (frm.is_dirty()) {
                    await frm.save();
                }

                dialog.hide();

                /*
                 * Submit directly, avoiding the overridden button.
                 */
                await frm.savesubmit();

            } catch (error) {
                console.error(
                    'Calibration submission failed:',
                    error
                );

                dialog.enable_primary_action();
            }
        }
    });

    dialog.show();
}


function reset_interval_confirmation(frm) {
    if (
        cint(
            frm.doc.custom_calibration_interval_confirmed ||
            0
        ) !== 0
    ) {
        frm.set_value(
            'custom_calibration_interval_confirmed',
            0
        );
    }
}


async function update_next_calibration_date(frm) {
    let months = cint(
        frm.doc.custom_calibration_interval_months || 0
    );

    let next_date = '';

    if (
        frm.doc.custom_calibration_date &&
        months > 0
    ) {
        next_date = moment(
            frm.doc.custom_calibration_date
        )
            .clone()
            .add(months, 'months')
            .format('YYYY-MM-DD');
    }

    if (
        (frm.doc.custom_next_calibration_date || '') !==
        next_date
    ) {
        await frm.set_value(
            'custom_next_calibration_date',
            next_date
        );
    }
}

frappe.ui.form.on('Equipment Component', {
    setup(frm) {
        install_component_safe_duplicate_handler(frm);
        set_component_parent_equipment_filter(frm);
    },

    onload(frm) {
        install_component_safe_duplicate_handler(frm);
        clear_component_identity_after_duplicate(frm);
        set_component_parent_equipment_filter(frm);
    },

    onload_post_render(frm) {
        install_component_safe_duplicate_handler(frm);
        clear_component_identity_after_duplicate(frm);

        setTimeout(function() {
            install_component_safe_duplicate_handler(frm);
        }, 300);
    },

    refresh(frm) {
        install_component_safe_duplicate_handler(frm);
        clear_component_identity_after_duplicate(frm);

        setTimeout(function() {
            install_component_safe_duplicate_handler(frm);
        }, 300);

        set_component_parent_equipment_filter(frm);
        update_component_display_name(frm);

        if (!frm.is_new()) {
            add_create_installation_ticket_button(frm);
        }
    },

    custom_serial_number(frm) {
        update_component_display_name(frm);
    },

    custom_equipment_type(frm) {
        update_component_display_name(frm);
    },

    custom_component_group(frm) {
        update_component_display_name(frm);
    },

    custom_item(frm) {
        fetch_component_item_name(frm);
    }
});



/* =========================
   SAFE COMPONENT DUPLICATION
========================= */

const COMPONENT_DUPLICATE_SESSION_KEY =
    'gotech_equipment_component_duplicate_context';

const COMPONENT_DUPLICATE_MAX_AGE_MS =
    2 * 60 * 1000;


function install_component_safe_duplicate_handler(frm) {
    if (frm.__gotech_component_duplicate_handler_installed) {
        return;
    }

    if (typeof frm.copy_doc !== 'function') {
        return;
    }

    let original_copy_doc = frm.copy_doc.bind(frm);

    frm.copy_doc = function() {
        let context = {
            source_name: frm.doc.name || '',
            created_at: Date.now()
        };

        try {
            window.sessionStorage.setItem(
                COMPONENT_DUPLICATE_SESSION_KEY,
                JSON.stringify(context)
            );
        } catch (e) {
            window.__gotech_component_duplicate_context =
                context;
        }

        return original_copy_doc();
    };

    frm.__gotech_component_duplicate_handler_installed = true;
}


function get_component_duplicate_context() {
    let context = null;

    try {
        let raw = window.sessionStorage.getItem(
            COMPONENT_DUPLICATE_SESSION_KEY
        );

        if (raw) {
            context = JSON.parse(raw);
        }
    } catch (e) {
        context =
            window.__gotech_component_duplicate_context ||
            null;
    }

    return context;
}


function clear_component_duplicate_context() {
    try {
        window.sessionStorage.removeItem(
            COMPONENT_DUPLICATE_SESSION_KEY
        );
    } catch (e) {
        // Ignore browser storage restrictions.
    }

    window.__gotech_component_duplicate_context = null;
}


function clear_component_identity_after_duplicate(frm) {
    if (!frm.is_new() || !frm.doc.__islocal) {
        return;
    }

    let context = get_component_duplicate_context();

    if (!context || !context.created_at) {
        return;
    }

    let age = Date.now() - Number(context.created_at);

    if (
        age < 0 ||
        age > COMPONENT_DUPLICATE_MAX_AGE_MS
    ) {
        clear_component_duplicate_context();
        return;
    }

    if (frm.__gotech_component_duplicate_cleared) {
        return;
    }

    frm.__gotech_component_duplicate_cleared = true;
    clear_component_duplicate_context();

    let clear_tasks = [];

    [
        'custom_serial_number',
        'custom_display_name',
        'custom_customer',
        'custom_branch',
        'custom_parent_equipment',
        'custom_company_workshop'
    ].forEach(function(fieldname) {
        if (
            frm.fields_dict[fieldname] &&
            frm.doc[fieldname]
        ) {
            clear_tasks.push(
                frm.set_value(fieldname, '')
            );
        }
    });

    Promise.all(clear_tasks).then(function() {
        update_component_display_name(frm);

        frappe.show_alert({
            message: __(
                'Component duplicated. Serial number, display name, customer, branch and location were cleared.'
            ),
            indicator: 'orange'
        });
    });
}


function fetch_component_item_name(frm) {
    if (!frm.doc.custom_item) {
        frm._component_item_name = '';
        update_component_display_name(frm);
        return;
    }

    frappe.db.get_value(
        'Item',
        frm.doc.custom_item,
        'item_name',
        function(r) {
            frm._component_item_name =
                (r && r.item_name) ? r.item_name : '';

            update_component_display_name(frm);
        }
    );
}


function update_component_display_name(frm) {
    // A permanent COMP-xxxxx ID is only available after the document exists.
    if (frm.is_new() || !frm.doc.name) {
        return;
    }

    const description =
        frm._component_item_name ||
        frm.doc.custom_equipment_type ||
        frm.doc.custom_component_group ||
        'Component';

    const parts = [
        description,
        frm.doc.name,
        frm.doc.custom_serial_number
    ].filter(Boolean);

    const display_name = parts.join(' - ');

    if (
        frm.fields_dict.custom_display_name &&
        (frm.doc.custom_display_name || '') !== display_name
    ) {
        frm.set_value('custom_display_name', display_name);
    }
}


/* =========================
   FILTERS
========================= */

function set_component_parent_equipment_filter(frm) {
    if (!frm.fields_dict.custom_parent_equipment) {
        return;
    }

    frm.set_query('custom_parent_equipment', function() {
        let filters = {};

        if (frm.doc.custom_customer) {
            filters.custom_parent_customer = frm.doc.custom_customer;
        }

        if (frm.doc.custom_branch) {
            filters.custom_branch = frm.doc.custom_branch;
        }

        return {
            filters: filters
        };
    });
}


/* =========================
   CREATE INSTALLATION TICKET
========================= */

function add_create_installation_ticket_button(frm) {
    frm.add_custom_button(
        __('Create Installation Ticket'),
        function() {
            open_component_installation_ticket_dialog(frm);
        },
        __('Actions')
    );
}


function open_component_installation_ticket_dialog(frm) {
    let dialog = new frappe.ui.Dialog({
        title: __('Create Component Installation Ticket'),
        size: 'large',
        fields: [
            {
                fieldtype: 'Section Break',
                label: __('Installation Destination')
            },
            {
                label: __('Customer'),
                fieldname: 'customer',
                fieldtype: 'Link',
                options: 'Customer',
                default: frm.doc.custom_customer || '',
                reqd: 1,
                onchange: function() {
                    let selected_customer = dialog.get_value('customer');

                    if (
                        dialog.get_value('branch') &&
                        selected_customer
                    ) {
                        dialog.set_value('branch', '');
                    }

                    if (
                        dialog.get_value('destination_equipment') &&
                        selected_customer
                    ) {
                        dialog.set_value('destination_equipment', '');
                    }
                }
            },
            {
                label: __('Branch'),
                fieldname: 'branch',
                fieldtype: 'Link',
                options: 'Client Branch',
                default: frm.doc.custom_branch || '',
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            custom_parent_customer:
                                dialog.get_value('customer') || ''
                        }
                    };
                },
                onchange: function() {
                    if (dialog.get_value('destination_equipment')) {
                        dialog.set_value('destination_equipment', '');
                    }
                }
            },
            {
                label: __('Destination Installed Equipment'),
                fieldname: 'destination_equipment',
                fieldtype: 'Link',
                options: 'Installed Equipment',
                default: frm.doc.custom_parent_equipment || '',
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            custom_parent_customer:
                                dialog.get_value('customer') || '',
                            custom_branch:
                                dialog.get_value('branch') || ''
                        }
                    };
                },
                onchange: function() {
                    let equipment_name =
                        dialog.get_value('destination_equipment');

                    if (!equipment_name) {
                        return;
                    }

                    frappe.db.get_value(
                        'Installed Equipment',
                        equipment_name,
                        [
                            'custom_parent_customer',
                            'custom_branch',
                            'custom_display_name',
                            'custom_asset_name'
                        ]
                    ).then(function(r) {
                        let equipment = r.message || {};

                        if (equipment.custom_parent_customer) {
                            dialog.set_value(
                                'customer',
                                equipment.custom_parent_customer
                            );
                        }

                        if (equipment.custom_branch) {
                            dialog.set_value(
                                'branch',
                                equipment.custom_branch
                            );
                        }

                        if (!dialog.get_value('subject')) {
                            let component_label =
                                frm.doc.custom_display_name ||
                                frm.doc.custom_equipment_type ||
                                frm.doc.name;

                            let equipment_label =
                                equipment.custom_display_name ||
                                equipment.custom_asset_name ||
                                equipment_name;

                            dialog.set_value(
                                'subject',
                                'Install ' +
                                component_label +
                                ' on ' +
                                equipment_label
                            );
                        }
                    });
                }
            },
            {
                fieldtype: 'Section Break',
                label: __('Ticket Details')
            },
            {
                label: __('Subject'),
                fieldname: 'subject',
                fieldtype: 'Data',
                default:
                    'Install ' +
                    (
                        frm.doc.custom_display_name ||
                        frm.doc.custom_equipment_type ||
                        frm.doc.name
                    ),
                reqd: 1
            },
            {
                label: __('Description'),
                fieldname: 'description',
                fieldtype: 'Small Text',
                reqd: 1
            },
            {
                label: __('Priority'),
                fieldname: 'priority',
                fieldtype: 'Select',
                options: 'Low\nMedium\nHigh\nUrgent',
                default: 'Medium',
                reqd: 1
            },
            {
                label: __('Work Type'),
                fieldname: 'work_type',
                fieldtype: 'Select',
                options: [
                    {
                        label: __('Direct Dispatch'),
                        value: 'Quick Intervention'
                    },
                    {
                        label: __('Planned Visit'),
                        value: 'Tech Mission'
                    }
                ],
                default: 'Quick Intervention',
                reqd: 1
            },
            {
                fieldtype: 'Section Break',
                label: __('Assignment')
            },
            {
                label: __('Planned Technicians'),
                fieldname: 'technicians',
                fieldtype: 'MultiSelectPills',
                reqd: 1,
                get_data: function(txt) {
                    return frappe.db.get_link_options(
                        'User',
                        txt,
                        {
                            enabled: 1
                        }
                    );
                }
            }
        ],
        primary_action_label: __('Create Installation Ticket'),
        primary_action: function(values) {
            create_component_installation_ticket(
                frm,
                dialog,
                values
            );
        }
    });

    dialog.show();
}


function create_component_installation_ticket(
    frm,
    dialog,
    values
) {
    let technicians = values.technicians || [];

    if (typeof technicians === 'string') {
        technicians = technicians
            .split(',')
            .map(function(value) {
                return value.trim();
            })
            .filter(Boolean);
    }

    if (!technicians.length) {
        frappe.msgprint(
            __('Please select at least one technician.')
        );
        return;
    }

    frappe.call({
        method:
            'maintenance_app.api.create_installation_ticket_from_component',
        args: {
            component_name: frm.doc.name,
            destination_equipment:
                values.destination_equipment,
            subject: values.subject,
            description: values.description,
            priority: values.priority,
            technicians: JSON.stringify(technicians),
            work_type: values.work_type
        },
        freeze: true,
        freeze_message: __(
            'Creating Component Installation Ticket...'
        ),
        callback: function(r) {
            if (!r.message || !r.message.ticket) {
                return;
            }

            dialog.hide();

            frappe.show_alert({
                message: __(
                    'Component Installation Ticket created successfully.'
                ),
                indicator: 'green'
            });

            frappe.set_route(
                'Form',
                'Service Ticket',
                r.message.ticket
            );
        }
    });
}

frappe.ui.form.on('Company Workshop', {
    custom_company: function(frm) {
        build_full_name(frm);
    },

    custom_workshop_name: function(frm) {
        build_full_name(frm);
    }
});

function build_full_name(frm) {
    if (frm.doc.custom_company && frm.doc.custom_workshop_name) {
        frm.set_value(
            "custom_full_name",
            frm.doc.custom_company + " - " + frm.doc.custom_workshop_name
        );
    }
}

frappe.ui.form.on('HSE Incident Report', {
    refresh(frm) {

        if (frm.is_new()) return;

        if (frm.doc.custom_incident_status === "Open") {

            frm.add_custom_button(__('Close Incident'), function () {

                frappe.confirm(
                    "Close this incident?",
                    function () {

                        frm.set_value("custom_incident_status", "Closed");

                        frm.save().then(() => {
                            frappe.show_alert({
                                message: "Incident Closed",
                                indicator: "green"
                            });
                        });

                    }
                );

            }, __('Actions'));

        }

        // Lock after closure
        if (frm.doc.custom_incident_status === "Closed") {
            frm.disable_form();
        }

        if (frm.doc.custom_incident_status === "Open") {

            frm.add_custom_button(__("Create Investigation"), function () {

                frappe.confirm("Create investigation ticket for this incident?", function () {

                    frappe.call({
                        method: "maintenance_app.api.create_investigation_ticket",
                        args: {
                            hse_report_name: frm.doc.name
                        },
                        callback: function (r) {
                            if (r.message && r.message.ticket) {
                                frappe.show_alert({
                                    message: "Investigation Ticket Created",
                                    indicator: "green"
                                });

                                frm.reload_doc();

                                frappe.set_route("Form", "Service Ticket", r.message.ticket);
                            }
                        }
                    });

                });

            }, __("Actions"));

        }

    }
});

