frappe.ui.form.on('MI Incident Detail', {
    custom_incident_type_name: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.custom_incident_type_name) return;

        frappe.db.get_value(
            "HSE Incident Type",
            row.custom_incident_type_name,
            [
                "custom_default_severity",
