});

frappe.ui.form.on('Mission Intervention', {
        refresh: function(frm) {
    setup_mi_form(frm);
    add_change_equipment_button(frm);
    add_change_component_button(frm);
    add_select_stock_component_button(frm);
    add_calibration_record_button(frm);
    add_commissioning_mi_button(frm);
    },



    // Trigger: Inserts date the moment the "+" button is clicked on the Config Change table
    custom_config_changes_add: function(frm, cdt, cdn) {
