function show_complete_work_dialog(frm) {
    let dialog = new frappe.ui.Dialog({
        title: __('Complete Work'),
        fields: [
            {
                label: __('Final Outcome'),
                fieldname: 'outcome',
                fieldtype: 'Select',
                options: [
                    'Work Completed',
                    'Continue Work',
                    'Waiting for Parts',
                    'Waiting for Client',
                    'To Quote (Billable)',
                    'Could Not Complete',
                    'False Call Out'
                ].join('\n'),
                default: frm.doc.custom_work_outcome || '',
                reqd: 1
            },
            {
                /*label: __('Fault Type'),
                fieldname: 'fault_type',
                fieldtype: 'Link',
                options: 'Fault Type',
                default: frm.doc.custom_fault_type || '',
                reqd: 1*/

                 label: __('Fault Type'),
                fieldname: 'fault_type',
                fieldtype: 'Link',
                options: 'Fault Type',
                default: frm.doc.custom_fault_type || '',
                reqd: frm.doc.custom_intervention_type === 'Repair' ? 1 : 0
            },
            {
                label: __('Technical Progress Notes'),
                fieldname: 'notes',
                fieldtype: 'Small Text',
                default: frm.doc.custom_work_progress || '',
                reqd: 1
            }
        ],
        primary_action_label: __('Complete Work'),
        primary_action(values) {
