            frm.set_value('custom_fault_type', values.fault_type);
            frm.set_value('custom_work_progress', values.notes);

            if (!frm.doc.custom_completed_time) {
                frm.set_value('custom_completed_time', frappe.datetime.now_datetime());
            }

            frm.set_value('custom_checkout_status', 'Work Completed');

            dialog.hide();

            frm.save().then(() => {
                frm.reload_doc().then(() => {
                    toggle_lock_state(frm);
