// Check-in and check-out with GPS

function get_current_gps() {
    return new Promise(function(resolve) {
        if (!navigator.geolocation) {
            console.warn("GPS is not supported by this browser.");
            resolve(null);
            return;
        }

        /*
         * Browser geolocation normally requires HTTPS.
         * Local HTTP testing will continue without GPS.
         */
        if (!window.isSecureContext) {
            console.warn(
                "GPS skipped because the page is not running in a secure context."
            );
            resolve(null);
            return;
        }

        navigator.geolocation.getCurrentPosition(
            function(position) {
                resolve({
                    latitude: position.coords.latitude,
                    longitude: position.coords.longitude,
                    accuracy: position.coords.accuracy
                });
            },
            function(error) {
                console.warn(
                    "GPS could not be obtained:",
                    error.code,
                    error.message
                );
                resolve(null);
            },
            {
                enableHighAccuracy: true,
                timeout: 15000,
                maximumAge: 0
            }
        );
    });
}


function sync_mi_to_mission_register(frm, callback) {
    if (!frm.doc.name || frm.is_new()) {
        if (callback) callback();
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.sync_mi_to_mission_register',
        args: {
            mi_name: frm.doc.name
        },
        freeze: false,
        callback: function() {
            if (callback) callback();
        }
    });
}


function final_check_out(frm) {
    if (!frm.doc.custom_completed_time) {
        frappe.msgprint(
            __('Please Complete Work before Check Out.')
        );
        return;
    }

    if (!frm.doc.custom_client_signature_received) {
        frappe.msgprint(
            __('Please mark Client Signed before Check Out.')
        );
        return;
    }

    get_current_gps().then(function(gps) {
        frm.set_value(
            'custom_end_time',
            frappe.datetime.now_datetime()
        );

        frm.set_value(
            'custom_checkout_status',
            'Checked Out'
        );

        if (gps) {
            if (frm.fields_dict.custom_checkout_latitude) {
                frm.set_value(
                    'custom_checkout_latitude',
                    gps.latitude
                );
            }

            if (frm.fields_dict.custom_checkout_longitude) {
                frm.set_value(
                    'custom_checkout_longitude',
                    gps.longitude
                );
            }

            if (frm.fields_dict.custom_checkout_accuracy) {
                frm.set_value(
                    'custom_checkout_accuracy',
                    gps.accuracy
                );
            }
        }

        calculate_hours(frm);

        frm.save().then(function() {
            sync_mi_to_mission_register(frm, function() {
                frm.reload_doc().then(function() {
                    setup_check_buttons(frm);

                    frappe.show_alert({
                        message: gps
                            ? __('Checked Out with GPS')
                            : __('Checked Out without GPS'),
                        indicator: gps ? 'green' : 'orange'
                    });
                });
            });
        });
    });
}

function setup_check_buttons(frm) {
    if (frm.is_new() || frm.doc.docstatus !== 0) {
        return;
    }

    frm.page.clear_primary_action();
    frm.page.clear_actions_menu();

    if (!frm.doc.custom_start_time) {
        frm.page.set_primary_action(__('Check In'), function() {

            if (
                frm.doc.custom_intervention_type === 'Specialised Testing' &&
                !frm.doc.custom_specialised_testing_type
            ) {
                frappe.msgprint(
                    __('Please select Specialised Testing Type before Check In.')
                );
                return;
            }

            if (
                frm.doc.custom_intervention_type === 'General Installation' &&
                !frm.doc.custom_general_installation_type
            ) {
                frappe.msgprint(
                    __('Please select General Installation Type before Check In.')
                );
                return;
            }

            get_current_gps().then(function(gps) {
                frm.set_value(
                    'custom_start_time',
                    frappe.datetime.now_datetime()
                );
                frm.set_value(
                    'custom_start_date',
                    frappe.datetime.get_today()
                );
                frm.set_value(
                    'custom_checkout_status',
                    'Checked In'
                );

                if (gps) {
                    if (frm.fields_dict.custom_checkin_latitude) {
                        frm.set_value(
                            'custom_checkin_latitude',
                            gps.latitude
                        );
                    }

                    if (frm.fields_dict.custom_checkin_longitude) {
                        frm.set_value(
                            'custom_checkin_longitude',
                            gps.longitude
                        );
                    }

                    if (frm.fields_dict.custom_checkin_accuracy) {
                        frm.set_value(
                            'custom_checkin_accuracy',
                            gps.accuracy
                        );
                    }
                }

                frm.save().then(function() {
                    sync_mi_to_mission_register(frm, function() {
                        frm.reload_doc().then(function() {
                            toggle_lock_state(frm);
                            toggle_intervention_fields(frm);
                            toggle_component_replacement_fields(frm);
                            toggle_config_changes_access(frm);
                            setup_check_buttons(frm);

                            frappe.show_alert({
                                message: gps
                                    ? __('Checked In with GPS')
                                    : __('Checked In without GPS'),
                                indicator: gps ? 'green' : 'orange'
                            });
                        });
                    });
                });
            });
        });

        return;
    }

    if (frm.doc.custom_start_time && !frm.doc.custom_completed_time) {
        frm.page.set_primary_action(__('Complete Work'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (frm.doc.custom_completed_time && !frm.doc.custom_client_signature_received) {
        frm.page.set_primary_action(__('Mark Client Signed'), function() {
            mark_client_signed(frm);
        });

        frm.page.add_action_item(__('Edit Work Outcome'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (frm.doc.custom_client_signature_received && !frm.doc.custom_end_time) {
        frm.page.set_primary_action(__('Check Out'), function() {
            final_check_out(frm);
        });

        frm.page.add_action_item(__('Edit Work Outcome'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (
        frm.doc.custom_start_time &&
        frm.doc.custom_completed_time &&
        frm.doc.custom_client_signature_received &&
        frm.doc.custom_end_time
    ) {
        frm.page.set_primary_action(__('Submit'), function() {
            frm.savesubmit();
        });
    }
}

function update_checkout_status(frm) {
    if (!frm.fields_dict.custom_checkout_status || frm.doc.docstatus === 1) {
        return;
    }

    let status = 'Not Started';

    if (frm.doc.custom_end_time) {
        status = 'Checked Out';
    } else if (frm.doc.custom_client_signature_received) {
        status = 'Client Signed';
    } else if (frm.doc.custom_completed_time) {
        status = 'Work Completed';
    } else if (frm.doc.custom_start_time) {
        status = 'Checked In';
    }

    if (frm.doc.custom_checkout_status !== status) {
        frm.set_value('custom_checkout_status', status);
    }
}

