function get_asset_change_tab_fieldname(frm) {
    const likely_fieldnames = [
        "custom_asset_change_tab",
        "asset_change_tab",
        "custom_asset_change_tab_break"
    ];

    for (const fieldname of likely_fieldnames) {
        if (frm.fields_dict[fieldname]) {
            return fieldname;
        }
    }

    const tab_field = (frm.meta.fields || []).find(function(df) {
        return (
            df.fieldtype === "Tab Break" &&
            String(df.label || "").trim().toLowerCase() === "asset change"
        );
    });

    return tab_field ? tab_field.fieldname : null;
}

function toggle_asset_change_tab(frm) {
    const tab_fieldname = get_asset_change_tab_fieldname(frm);
    if (!tab_fieldname) return;

    const type = frm.doc.custom_intervention_type || "";
    const checked_in = !!frm.doc.custom_start_time;
    const submitted = frm.doc.docstatus === 1;

    const show_tab = checked_in && (
        type === "Swap" ||
        type === "Asset Relocation" ||
        type === "Loan" ||
        type === "Installation" ||
        type === "Commissioning" ||
        !!frm.doc.custom_component_installation ||
        !!frm.doc.custom_component_replaced
    );

    frm.set_df_property(tab_fieldname, "hidden", show_tab ? 0 : 1);
    frm.set_df_property(tab_fieldname, "read_only", submitted ? 1 : 0);
}

function toggle_intervention_fields(frm) {
    let type = frm.doc.custom_intervention_type || "";
    let checked_in = !!frm.doc.custom_start_time;
    let submitted = frm.doc.docstatus === 1;
    let outcome = frm.doc.custom_removed_asset_outcome || "";
    let component_replaced = !!frm.doc.custom_component_replaced;
    let component_installation = !!frm.doc.custom_component_installation;

    let asset_change_fields = [
        "custom_new_branch",
        "custom_replacement_source",
        "custom_replacement_source_branch",
        "custom_replacement_warehouse",
        "custom_removed_asset_outcome",
        "custom_company_workshop",
        "custom_new_make",
        "custom_new_model",
        "custom_new_serial",
        "custom_new_asset",
        "custom_loan_required",
        "custom_loan_approved",
        "custom_loan_return",
        "custom_asset_change_reason",
        "custom_current_site_position",
        "custom_replacement_site_position",
        "custom_equipment_name_action",
        "custom_new_current_equipment_name",
        "custom_new_replacement_equipment_name"
    ];

    asset_change_fields.forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "hidden", 1);
            frm.set_df_property(fieldname, "reqd", 0);
        }
    });

    function show_fields(fields) {
        fields.forEach(function(fieldname) {
            if (frm.fields_dict[fieldname]) {
                frm.set_df_property(fieldname, "hidden", 0);
                frm.set_df_property(fieldname, "reqd", 0);
            }
        });
    }

    function require_fields(fields) {
        fields.forEach(function(fieldname) {
            if (frm.fields_dict[fieldname]) {
                frm.set_df_property(fieldname, "reqd", 1);
            }
        });
    }

    if (!checked_in) {
        return;
    }

    // Submitted records remain visible for reference, but are read-only.
    if (submitted) {
        let reference_fields = [
            "custom_new_branch",
            "custom_replacement_source",
            "custom_replacement_source_branch",
            "custom_replacement_warehouse",
            "custom_removed_asset_outcome",
            "custom_company_workshop",
            "custom_new_make",
            "custom_new_model",
            "custom_new_serial",
            "custom_new_asset",
            "custom_asset_change_reason",
            "custom_current_site_position",
            "custom_replacement_site_position",
            "custom_equipment_name_action",
            "custom_new_current_equipment_name",
            "custom_new_replacement_equipment_name"
        ];

        reference_fields.forEach(function(fieldname) {
            if (
                frm.fields_dict[fieldname] &&
                frm.doc[fieldname] !== undefined &&
                frm.doc[fieldname] !== null &&
                frm.doc[fieldname] !== ""
            ) {
                frm.set_df_property(fieldname, "hidden", 0);
                frm.set_df_property(fieldname, "read_only", 1);
                frm.set_df_property(fieldname, "reqd", 0);
            }
        });

        return;
    }

    // Install a component into an empty position on the current equipment.
    if (component_installation) {
        let source = frm.doc.custom_replacement_source || "";

        show_fields([
            "custom_replacement_source"
        ]);

        require_fields([
            "custom_replacement_source"
        ]);

        if (source === "Another Site") {
            show_fields(["custom_replacement_source_branch"]);
            require_fields(["custom_replacement_source_branch"]);
        }

        if (source === "Stock") {
            show_fields(["custom_replacement_warehouse"]);
            require_fields(["custom_replacement_warehouse"]);
        }

        if (source === "Workshop") {
            show_fields(["custom_company_workshop"]);
            require_fields(["custom_company_workshop"]);
        }

        return;
    }

    // Component swap: the parent equipment remains at the site.
    if (type === "Swap" && component_replaced) {
        let source = frm.doc.custom_replacement_source || "";

        show_fields([
            "custom_replacement_source",
            "custom_removed_asset_outcome"
        ]);

        require_fields([
            "custom_replacement_source",
            "custom_removed_asset_outcome"
        ]);

        if (source === "Another Site") {
            show_fields(["custom_replacement_source_branch"]);
            require_fields(["custom_replacement_source_branch"]);
        }

        if (source === "Stock") {
            show_fields(["custom_replacement_warehouse"]);
            require_fields(["custom_replacement_warehouse"]);
        }

        if (
            outcome === "Workshop for Repair" ||
            source === "Workshop"
        ) {
            show_fields(["custom_company_workshop"]);
            require_fields(["custom_company_workshop"]);
        }

        return;
    }

    // Whole-equipment swap/removal.
    if (type === "Swap") {
        show_fields([
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_replacement_source",
            "custom_removed_asset_outcome",
            "custom_asset_change_reason"
        ]);

        require_fields([
            "custom_replacement_source",
            "custom_removed_asset_outcome",
            "custom_asset_change_reason"
        ]);

        if (
            outcome === "Workshop for Repair" ||
            frm.doc.custom_replacement_source === "Workshop"
        ) {
            show_fields(["custom_company_workshop"]);
            require_fields(["custom_company_workshop"]);
        }

        if (frm.doc.custom_replacement_source === "Another Site") {
            show_fields(["custom_replacement_source_branch"]);
            require_fields(["custom_replacement_source_branch"]);
        }

        if (outcome === "Installed at Another Site") {
            show_fields(["custom_new_branch"]);
            require_fields(["custom_new_branch"]);
        }

        if (frm.doc.custom_new_asset) {
            show_fields(["custom_equipment_name_action"]);
            require_fields(["custom_equipment_name_action"]);

            if (frm.doc.custom_equipment_name_action === "Set Names Manually") {
                show_fields([
                    "custom_new_current_equipment_name",
                    "custom_new_replacement_equipment_name"
                ]);
                require_fields([
                    "custom_new_current_equipment_name",
                    "custom_new_replacement_equipment_name"
                ]);
            }
        }

        if (frm.doc.custom_replacement_source === "Same Site") {
            show_fields([
                "custom_current_site_position",
                "custom_replacement_site_position"
            ]);
            require_fields(["custom_new_asset"]);
            fetch_current_asset_position(frm);
            fetch_replacement_asset_details(frm);
        }

        return;
    }

    if (type === "Asset Relocation") {
        show_fields([
            "custom_new_branch",
            "custom_asset_change_reason"
        ]);
        require_fields([
            "custom_new_branch",
            "custom_asset_change_reason"
        ]);
        return;
    }

    if (type === "Loan") {
        show_fields([
            "custom_new_asset",
            "custom_new_branch",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return",
            "custom_removed_asset_outcome",
            "custom_asset_change_reason"
        ]);

        if (outcome === "Workshop for Repair") {
            show_fields(["custom_company_workshop"]);
        }
        return;
    }

    if (type === "Installation" || type === "Commissioning") {
        show_fields([
            "custom_new_branch",
            "custom_asset_change_reason"
        ]);
        return;
    }

    if (type === "Repair") {
        show_fields(["custom_asset_change_reason"]);
    }
}

/* =========================
   COMPONENT REPLACEMENT VISIBILITY
========================= */

function toggle_component_replacement_fields(frm) {
    let checked_in = !!frm.doc.custom_start_time;
    let submitted = frm.doc.docstatus === 1;
    let component_replaced = !!frm.doc.custom_component_replaced;
    let component_installation = !!frm.doc.custom_component_installation;
    let type = frm.doc.custom_intervention_type || "";
    let source = frm.doc.custom_replacement_source || "";

    // These are component-only fields. Shared whole-equipment movement fields
    // are controlled by toggle_intervention_fields().
    let component_fields = [
        "custom_equipment_component",
        "custom_new_equipment_component",
        "custom_component_item",
        "custom_component_serial",
        "custom_component_brand",
        "custom_component_model",
        "custom_new_component_item",
        "custom_new_component_serial",
        "custom_new_component_brand",
        "custom_new_component_model",
        "custom_component_replacement_reason"
    ];

    component_fields.forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "hidden", 1);
            frm.set_df_property(fieldname, "reqd", 0);
        }
    });

    // Show the original component snapshot only when at least one
    // snapshot value exists. Equipment-only tickets remain clean.
    let has_component_snapshot = [
        "custom_component_group",
        "custom_component_item",
        "custom_component_serial",
        "custom_component_brand",
        "custom_component_model"
    ].some(function(fieldname) {
        return (
            frm.doc[fieldname] !== undefined &&
            frm.doc[fieldname] !== null &&
            String(frm.doc[fieldname]).trim() !== ""
        );
    });

    if (has_component_snapshot) {
        [
            "custom_component_group",
            "custom_component_item",
            "custom_component_serial",
            "custom_component_brand",
            "custom_component_model"
        ].forEach(function(fieldname) {
            if (frm.fields_dict[fieldname]) {
                frm.set_df_property(fieldname, "hidden", 0);
                frm.set_df_property(fieldname, "read_only", 1);
                frm.set_df_property(fieldname, "reqd", 0);
            }
        });
    }

    if (frm.fields_dict.custom_component_replaced) {
        frm.set_df_property(
            "custom_component_replaced",
            "hidden",
            checked_in && !submitted && type === "Swap" ? 0 : 1
        );
    }

    if (frm.fields_dict.custom_component_installation) {
        frm.set_df_property(
            "custom_component_installation",
            "hidden",
            checked_in && !submitted &&
            ["Installation", "Commissioning", "Service", "Repair"].includes(type)
                ? 0
                : 1
        );
    }

    if (!checked_in) {
        return;
    }

    if (submitted) {
        if (component_replaced || component_installation) {
            component_fields.forEach(function(fieldname) {
                if (
                    frm.fields_dict[fieldname] &&
                    frm.doc[fieldname] !== undefined &&
                    frm.doc[fieldname] !== null &&
                    frm.doc[fieldname] !== ""
                ) {
                    frm.set_df_property(fieldname, "hidden", 0);
                    frm.set_df_property(fieldname, "read_only", 1);
                    frm.set_df_property(fieldname, "reqd", 0);
                }
            });

            [
                "custom_component_replaced",
                "custom_component_installation"
            ].forEach(function(fieldname) {
                if (frm.fields_dict[fieldname] && frm.doc[fieldname]) {
                    frm.set_df_property(fieldname, "hidden", 0);
                    frm.set_df_property(fieldname, "read_only", 1);
                }
            });
        }

        return;
    }

    if (!component_replaced && !component_installation) {
        return;
    }

    // Common incoming-component fields.
    [
        "custom_replacement_source",
        "custom_new_equipment_component",
        "custom_new_component_item",
        "custom_new_component_serial",
        "custom_new_component_brand",
        "custom_new_component_model",
        "custom_component_replacement_reason"
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "hidden", 0);
        }
    });

    [
        "custom_replacement_source",
        "custom_new_equipment_component",
        "custom_component_replacement_reason"
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "reqd", 1);
        }
    });

    if (component_replaced) {
        [
            "custom_equipment_component",
            "custom_component_item",
            "custom_component_serial",
            "custom_component_brand",
            "custom_component_model"
        ].forEach(function(fieldname) {
            if (frm.fields_dict[fieldname]) {
                frm.set_df_property(fieldname, "hidden", 0);
            }
        });

        if (frm.fields_dict.custom_equipment_component) {
            frm.set_df_property("custom_equipment_component", "reqd", 1);
        }

        if (frm.fields_dict.custom_removed_asset_outcome) {
            frm.set_df_property("custom_removed_asset_outcome", "hidden", 0);
            frm.set_df_property("custom_removed_asset_outcome", "reqd", 1);
        }
    }

    // Installation-only deliberately keeps outgoing component and
    // removed-component outcome hidden.
    if (
        source === "Another Site" &&
        frm.fields_dict.custom_replacement_source_branch
    ) {
        frm.set_df_property("custom_replacement_source_branch", "hidden", 0);
        frm.set_df_property("custom_replacement_source_branch", "reqd", 1);
    }

    if (
        source === "Stock" &&
        frm.fields_dict.custom_replacement_warehouse
    ) {
        frm.set_df_property("custom_replacement_warehouse", "hidden", 0);
        frm.set_df_property("custom_replacement_warehouse", "reqd", 1);
    }

    if (
        (
            source === "Workshop" ||
            (
                component_replaced &&
                frm.doc.custom_removed_asset_outcome === "Workshop for Repair"
            )
        ) &&
        frm.fields_dict.custom_company_workshop
    ) {
        frm.set_df_property("custom_company_workshop", "hidden", 0);
        frm.set_df_property("custom_company_workshop", "reqd", 1);
    }
}


