   CALIBRATION RECORD
========================= */

function add_calibration_record_button(frm) {
    try {
        frm.remove_custom_button(__('Create Calibration Record'), __('Calibration'));
        frm.remove_custom_button(__('Open Calibration Record'), __('Calibration'));
    } catch (e) {
        // Safe if the button does not yet exist.
    }

    if (frm.is_new()) return;
    if (frm.doc.docstatus === 2) return;
    if (frm.doc.custom_intervention_type !== 'Calibration') return;

    if (frm.doc.custom_calibration_record) {
        frm.add_custom_button(
            __('Open Calibration Record'),
            function() {
                frappe.set_route(
                    'Form',
                    'Calibration Record',
                    frm.doc.custom_calibration_record
                );
            },
            __('Calibration')
        );
        return;
    }

    frm.add_custom_button(
        __('Create Calibration Record'),
        function() {
            create_calibration_record_from_mi(frm);
        },
        __('Calibration')
    );
}

function create_calibration_record_from_mi(frm) {
    if (!frm.doc.custom_service_ticket) {
        frappe.msgprint(__('This intervention is not linked to a Service Ticket.'));
        return;
    }

    if (!frm.doc.custom_asset && !frm.doc.custom_equipment_component) {
        frappe.msgprint(
            __('Please link an Installed Equipment or Equipment Component before creating the Calibration Record.')
        );
        return;
    }

    frappe.prompt(
        [
            {
                label: __('Calibration Date'),
                fieldname: 'calibration_date',
                fieldtype: 'Datetime',
                default: frappe.datetime.now_datetime(),
                reqd: 1
            },
            {
                label: __('Calibration Type'),
                fieldname: 'calibration_type',
                fieldtype: 'Select',
                options: [
                    'Initial Calibration',
                    'Periodic Calibration',
                    'Post-Repair Calibration',
                    'Verification',
                    'Adjustment and Calibration'
                ].join('\n'),
                reqd: 1
            },
            {
                label: __('Reference Standard'),
                fieldname: 'reference_standard',
                fieldtype: 'Data',
                reqd: 1
            }
        ],
        function(values) {
            let affected_name =
                frm.doc.custom_target_component_name ||
                frm.doc.custom_component_item ||
                frm.doc.custom_asset ||
                frm.doc.custom_equipment_component ||
                frm.doc.name;

            let calibration_doc = {
                doctype: 'Calibration Record',
                custom_calibration_title:
                    __('Calibration - {0} - {1}', [
                        affected_name,
                        frm.doc.name
                    ]),
                custom_service_ticket: frm.doc.custom_service_ticket || '',
                custom_tech_mission: frm.doc.custom_parent_mission || '',
                custom_mission_intervention: frm.doc.name,
                custom_customer: frm.doc.custom_parent_customer || '',
                custom_branch: frm.doc.custom_branch || '',
                custom_installed_equipment: frm.doc.custom_asset || '',
                custom_equipment_component:
                    frm.doc.custom_equipment_component || '',

                // Equipment/component snapshot
                custom_equipment_description:
                    frm.doc.custom_target_component_name ||
                    frm.doc.custom_component_item ||
                    frm.doc.custom_asset ||
                    frm.doc.custom_equipment_component ||
                    '',
                custom_client_asset_code:
                    frm.doc.custom_client_asset_code || '',
                custom_make:
                    frm.doc.custom_component_brand ||
                    frm.doc.custom_make ||
                    '',
                custom_model:
                    frm.doc.custom_component_model ||
                    frm.doc.custom_model ||
                    '',
                custom_serial_number:
                    frm.doc.custom_component_serial ||
                    frm.doc.custom_asset_id ||
                    '',
                custom_calibration_location:
                    frm.doc.custom_branch || '',

                custom_calibration_date: values.calibration_date,
                custom_calibration_type: values.calibration_type,
                custom_reference_standard: values.reference_standard,
                custom_technician: frm.doc.custom_technician || '',
                custom_calibration_status: 'Draft'
            };

            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: calibration_doc
                },
                freeze: true,
                freeze_message: __('Creating Calibration Record...'),
                callback: function(r) {
                    if (!r.message || !r.message.name) return;

                    let calibration_name = r.message.name;

                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Mission Intervention',
                            name: frm.doc.name,
                            fieldname: 'custom_calibration_record',
                            value: calibration_name
                        },
                        callback: function() {
                            frappe.call({
                                method: 'frappe.client.set_value',
                                args: {
                                    doctype: 'Service Ticket',
                                    name: frm.doc.custom_service_ticket,
                                    fieldname: 'custom_calibration_record',
                                    value: calibration_name
                                },
                                callback: function() {
                                    frm.reload_doc().then(function() {
                                        frappe.set_route(
                                            'Form',
                                            'Calibration Record',
                                            calibration_name
                                        );
                                    });
                                }
                            });
                        }
                    });
                }
            });
        },
        __('Create Calibration Record'),
        __('Create')
    );
}

