function add_select_stock_component_button(frm) {
    // Remove the old copy first so refresh/field changes never duplicate it.
    try {
        frm.remove_custom_button(__('Select Stock Component'), __('Component'));
    } catch (e) {
        // Safe on older Frappe builds where the button does not yet exist.
    }

    if (frm.is_new() || frm.doc.docstatus !== 0) return;
    if (!frm.doc.custom_start_time) return;
    const component_action =
        !!frm.doc.custom_component_replaced ||
        !!frm.doc.custom_component_installation;

    if (!component_action) return;
    if (frm.doc.custom_replacement_source !== 'Stock') return;
    if (!frm.doc.custom_replacement_warehouse) return;
    if (
        frm.doc.custom_component_replaced &&
        !frm.doc.custom_equipment_component
    ) return;

    frm.add_custom_button(
        __('Select Stock Component'),
        function() {
            open_stock_component_item_dialog(frm);
        },
        __('Component')
    );
}

function open_stock_component_item_dialog(frm) {
    frappe.call({
        method: 'maintenance_app.api.get_stock_component_items',
        args: {
            warehouse: frm.doc.custom_replacement_warehouse,
            outgoing_component: frm.doc.custom_equipment_component || "",
            search_text: ''
        },
        freeze: true,
        freeze_message: __('Loading compatible stock items...'),
        callback: function(r) {
            let items = r.message || [];

            if (!items.length) {
                frappe.msgprint(
                    __('No compatible serialized component Items are available in warehouse {0}.', [
                        frm.doc.custom_replacement_warehouse
                    ])
                );
                return;
            }

            let option_map = {};
            let options = items.map(function(row) {
                let label = row.item_code;

                if (row.item_name && row.item_name !== row.item_code) {
                    label += ' — ' + row.item_name;
                }

                if (row.brand) {
                    label += ' — ' + row.brand;
                }

                label += ' (' + cint(row.available_serial_count || 0) + ' available)';
                option_map[label] = row;
                return label;
            });

            frappe.prompt(
                [
                    {
                        label: __('Stock Item'),
                        fieldname: 'item_label',
                        fieldtype: 'Select',
                        options: options.join('\n'),
                        reqd: 1
                    }
                ],
                function(values) {
                    let selected = option_map[values.item_label];

                    if (!selected || !selected.item_code) {
                        frappe.throw(__('The selected stock Item is invalid.'));
                    }

                    open_stock_component_serial_dialog(frm, selected);
                },
                __('Select Component Item'),
                __('Next')
            );
        }
    });
}

function open_stock_component_serial_dialog(frm, item) {
    frappe.call({
        method: 'maintenance_app.api.get_available_component_serials',
        args: {
            warehouse: frm.doc.custom_replacement_warehouse,
            item_code: item.item_code,
            search_text: ''
        },
        freeze: true,
        freeze_message: __('Loading available serial numbers...'),
        callback: function(r) {
            let serials = r.message || [];

            if (!serials.length) {
                frappe.msgprint(
                    __('No available Serial Nos were found for Item {0} in warehouse {1}.', [
                        item.item_code,
                        frm.doc.custom_replacement_warehouse
                    ])
                );
                return;
            }

            let option_map = {};
            let options = serials.map(function(row) {
                let label = row.serial_no;

                if (row.equipment_component) {
                    label += ' — ' + row.equipment_component;
                } else {
                    label += ' — ' + __('New COMP record');
                }

                option_map[label] = row;
                return label;
            });

            frappe.prompt(
                [
                    {
                        label: __('Serial No'),
                        fieldname: 'serial_label',
                        fieldtype: 'Select',
                        options: options.join('\n'),
                        reqd: 1
                    }
                ],
                function(values) {
                    let selected = option_map[values.serial_label];

                    if (!selected || !selected.serial_no) {
                        frappe.throw(__('The selected Serial No is invalid.'));
                    }

                    register_stock_component_on_mi(
                        frm,
                        item.item_code,
                        selected.serial_no
                    );
                },
                __('Select Serial No'),
                __('Use Component')
            );
        }
    });
}

function register_stock_component_on_mi(frm, item_code, serial_no) {
    frappe.call({
        method: 'maintenance_app.api.find_or_create_stock_equipment_component',
        args: {
            mi_name: frm.doc.name,
            item_code: item_code,
            serial_no: serial_no,
            warehouse: frm.doc.custom_replacement_warehouse
        },
        freeze: true,
        freeze_message: __('Registering stock component...'),
        callback: function(r) {
            let result = r.message || {};

            if (!result.equipment_component) {
                frappe.throw(
                    __('The server did not return an Equipment Component.')
                );
            }

            frm.set_value(
                'custom_new_equipment_component',
                result.equipment_component
            ).then(function() {
                upsert_component_replacement_part_row(frm, result);
                fetch_component_snapshot(frm, true);
                frm.refresh_field('custom_new_equipment_component');

                frappe.show_alert({
                    message: result.created
                        ? __('Equipment Component {0} was created and selected.', [
                            result.equipment_component
                        ])
                        : __('Equipment Component {0} was selected.', [
                            result.equipment_component
                        ]),
                    indicator: 'green'
                });
            });
        }
    });
}

function upsert_component_replacement_part_row(frm, result) {
    let rows = frm.doc.custom_parts_table || [];
    let row = rows.find(function(part) {
        return !!part.custom_is_component_replacement;
    });

    if (!row) {
        row = frm.add_child('custom_parts_table');
    }

    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_item_code',
        result.item_code || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_item_name',
        result.item_name || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_brand',
        result.brand || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_warehouse',
        result.warehouse || frm.doc.custom_replacement_warehouse || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_qty',
        1
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_serial_no',
        result.serial_no || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_equipment_component',
        result.equipment_component || ''
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_is_component_replacement',
        1
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_stock_issued',
        0
    );
    frappe.model.set_value(
        row.doctype,
        row.name,
        'custom_stock_entry',
        ''
    );

    frm.refresh_field('custom_parts_table');
    frm.dirty();
}

function clear_draft_stock_replacement_row(frm) {
    if (!frm.doc || frm.doc.docstatus !== 0) return;
    if (!frm.doc.custom_parts_table) return;

    let remaining = (frm.doc.custom_parts_table || []).filter(function(row) {
        // Never remove a row after a stock movement was recorded.
        return !(
            row.custom_is_component_replacement &&
            !row.custom_stock_issued &&
            !row.custom_stock_entry
        );
    });

    if (remaining.length !== frm.doc.custom_parts_table.length) {
        frm.doc.custom_parts_table = remaining;
        frm.refresh_field('custom_parts_table');
        frm.dirty();
    }
}

function validate_stock_component_replacement(frm) {
    if (
        (
            !frm.doc.custom_component_replaced &&
            !frm.doc.custom_component_installation
        ) ||
        frm.doc.custom_replacement_source !== 'Stock'
    ) {
        return;
    }

    if (!frm.doc.custom_replacement_warehouse) {
        frappe.throw(__('Replacement Source Warehouse is required.'));
    }

    if (!frm.doc.custom_new_equipment_component) {
        frappe.throw(
            __('Please use Select Stock Component before submitting.')
        );
    }

    let matching_rows = (frm.doc.custom_parts_table || []).filter(function(row) {
        return (
            !!row.custom_is_component_replacement &&
            row.custom_equipment_component ===
                frm.doc.custom_new_equipment_component
        );
    });

    if (matching_rows.length !== 1) {
        frappe.throw(
            __('Exactly one matching component-replacement row is required in Parts Used.')
        );
    }

    let row = matching_rows[0];

    if (!row.custom_item_code) {
        frappe.throw(__('Item Code is missing from the replacement parts row.'));
    }

    if (!row.custom_serial_no) {
        frappe.throw(__('Serial No is missing from the replacement parts row.'));
    }

    if (!row.custom_warehouse) {
        frappe.throw(__('Warehouse is missing from the replacement parts row.'));
    }

    if (row.custom_warehouse !== frm.doc.custom_replacement_warehouse) {
        frappe.throw(
            __('The replacement parts row warehouse does not match the selected source warehouse.')
        );
    }

    if (flt(row.custom_qty) !== 1) {
        frappe.throw(
            __('A serialized component replacement must have Qty = 1.')
        );
    }

    if (row.custom_stock_issued || row.custom_stock_entry) {
        frappe.throw(
            __('The selected component has already been marked as issued.')
        );
    }
}

/* ============================================================
   COMMISSIONING MI
   Supports:
   - Whole-equipment Installation
   - Whole-equipment Swap
   - Component Installation
   - Component Swap
============================================================ */

function add_commissioning_mi_button(frm) {
    try {
        frm.remove_custom_button(
            __('Create Commissioning MI'),
            __('Commissioning')
        );
    } catch (e) {
        // Safe when the button does not exist yet.
    }

    if (frm.is_new() || frm.doc.docstatus !== 1) return;

    const type = frm.doc.custom_intervention_type || '';

    const component_installation = (
        type === 'Installation' &&
        !!frm.doc.custom_component_installation &&
        !!frm.doc.custom_new_equipment_component &&
        !!frm.doc.custom_asset
    );

    const component_swap = (
        type === 'Swap' &&
        !!frm.doc.custom_component_replaced &&
        !!frm.doc.custom_new_equipment_component &&
        !!frm.doc.custom_asset
    );

    const whole_equipment_installation = (
        type === 'Installation' &&
        !frm.doc.custom_component_installation &&
        !!frm.doc.custom_asset
    );

    const whole_equipment_swap = (
        type === 'Swap' &&
        !frm.doc.custom_component_replaced &&
        !frm.doc.custom_component_installation &&
        !!frm.doc.custom_new_asset
    );

    const eligible = (
        component_installation ||
        component_swap ||
        whole_equipment_installation ||
        whole_equipment_swap
    );

    if (!eligible) return;

    frm.add_custom_button(
        __('Create Commissioning MI'),
        function() {
            frappe.call({
                method:
                    'maintenance_app.api.create_commissioning_intervention_from_mi',
                args: {
                    source_mi_name: frm.doc.name
                },
                freeze: true,
                freeze_message: __('Creating Commissioning MI...'),
                callback: function(r) {
                    const result = r.message || {};

                    if (!result.intervention) {
                        frappe.msgprint(
                            __('The server did not return a Commissioning MI.')
                        );
                        return;
                    }

                    frappe.show_alert({
                        message: result.created
                            ? __('Commissioning MI created')
                            : __('Existing Commissioning MI opened'),
                        indicator: result.created ? 'green' : 'blue'
                    });

                    frappe.set_route(
                        'Form',
                        'Mission Intervention',
                        result.intervention
                    );
                }
            });
        },
        __('Commissioning')
    );
}

frappe.ui.form.on('Tech Mission', {
    refresh: function(frm) {
        add_mission_buttons(frm);
    }
});

function add_mission_buttons(frm) {
    frm.clear_custom_buttons();

    if (frm.is_new()) return;

    if (['Closed', 'Cancelled'].includes(frm.doc.custom_mission_status)) {
        return;
    }

    add_mission_management_buttons(frm);

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Mission Intervention',
            filters: {
                custom_parent_mission: frm.doc.name
            },
            fields: [
                'name',
                'docstatus',
                'custom_work_outcome',
                'creation'
            ],
            order_by: 'creation desc',
            limit_page_length: 50
        },
        callback: function(r) {
            let interventions = r.message || [];
            let has_any_mi = interventions.length > 0;
            let open_mi = null;

            interventions.forEach(function(row) {
                if (row.docstatus === 0 && !open_mi) {
                    open_mi = row.name;
                }
            });

            if (has_any_mi) {
                frm.add_custom_button(
                    __('Add Additional MI'),
                    function() {
                        create_additional_mi(frm);
                    },
                    __('Actions')
                );
            }

            if (frm.doc.custom_mission_status !== 'Completed') {
                if (open_mi) {
                    frm.add_custom_button(
                        __('Open Current Intervention'),
                        function() {
                            frappe.set_route(
                                'Form',
                                'Mission Intervention',
                                open_mi
                            );
                        },
                        __('Actions')
                    );
                } else {
                    let button_label = has_any_mi
                        ? __('Create Follow-up MI')
                        : __('Create First Intervention');

                    frm.add_custom_button(
                        button_label,
                        function() {
                            create_intervention(frm);
                        },
                        __('Actions')
                    );
                }
            }
        }
    });
}

function add_mission_management_buttons(frm) {
    if (frm.doc.custom_mission_status === 'Completed') {
        return;
    }

    frm.add_custom_button(
        __('Replace Technician'),
        function() {
            open_replace_technician_dialog(frm, false);
        },
        __('Manage Mission')
    );

    frm.add_custom_button(
        __('Add Technician'),
        function() {
            open_add_technician_dialog(frm);
        },
        __('Manage Mission')
    );

    frm.add_custom_button(
        __('Remove Technician'),
        function() {
            open_remove_technician_dialog(frm);
        },
        __('Manage Mission')
    );

    frm.add_custom_button(
        __('Change Vehicle'),
        function() {
            open_change_vehicle_dialog(frm);
        },
        __('Manage Mission')
    );

    frm.add_custom_button(
        __('Reschedule Mission'),
        function() {
            open_reschedule_dialog(frm);
        },
        __('Manage Mission')
    );

    frm.add_custom_button(
