function get_team_rows(frm) {
    return (frm.doc.custom_planned_team || [])
        .filter(row => !!row.custom_technician)
        .map(row => ({
            technician: row.custom_technician,
            vehicle: row.custom_assigned_vehicle || ''
        }));
}

function get_assigned_technicians(frm) {
    return get_team_rows(frm).map(row => row.technician);
}

function get_vehicle_for_technician(frm, technician) {
    let row = get_team_rows(frm).find(
        item => item.technician === technician
    );

    return row ? (row.vehicle || '') : '';
}

function internal_vehicle_required(frm) {
    return !frm.doc.custom_external_vehicle;
}

function validate_vehicle_choice(frm, technician, vehicle) {
    if (
        internal_vehicle_required(frm) &&
        !vehicle
    ) {
        frappe.msgprint(
            __('Please assign a Vehicle to {0}, or fill Hired / External Vehicle on the mission.', [
                technician
            ])
        );
        return false;
    }

    return true;
}

function get_schedule_fields(frm) {
    return [
        {
            label: __('New Planned Start'),
            fieldname: 'planned_start',
            fieldtype: 'Datetime',
            default: frm.doc.custom_planned_starttime,
            reqd: 1
        },
        {
            label: __('New Planned End'),
            fieldname: 'planned_end',
            fieldtype: 'Datetime',
            default: frm.doc.custom_planned_endtime,
            reqd: 1
        }
    ];
}

function open_replace_technician_dialog(frm, include_schedule) {
    let assigned = get_assigned_technicians(frm);

    if (!assigned.length) {
        frappe.msgprint(
            __('No technician is currently assigned to this mission.')
        );
        return;
    }

    let fields = [
        {
            label: __('Current Technician'),
            fieldname: 'old_technician',
            fieldtype: 'Select',
            options: assigned.join('\n'),
            reqd: 1
        },
        {
            label: __('New Technician'),
            fieldname: 'new_technician',
            fieldtype: 'Link',
            options: 'User',
            reqd: 1,
            get_query: function() {
                return {
                    filters: {
                        enabled: 1
                    }
                };
            }
        },
        {
            label: __('Assigned Vehicle'),
            fieldname: 'assigned_vehicle',
            fieldtype: 'Link',
            options: 'Vehicle'
        }
    ];

    if (include_schedule) {
        fields = fields.concat(get_schedule_fields(frm));
    }

    fields.push({
        label: __('Reason'),
        fieldname: 'reason',
        fieldtype: 'Small Text',
        reqd: 1
    });

    let dialog = new frappe.ui.Dialog({
        title: include_schedule
            ? __('Reassign and Reschedule Mission')
            : __('Replace Technician'),
        fields: fields,
        primary_action_label: __('Update Mission'),
        primary_action: function(values) {
            if (
                !validate_vehicle_choice(
                    frm,
                    values.new_technician,
                    values.assigned_vehicle
                )
            ) {
                return;
            }

            if (include_schedule) {
                let start = moment(values.planned_start);
                let end = moment(values.planned_end);

                if (!end.isAfter(start)) {
                    frappe.msgprint(
                        __('Planned End must be after Planned Start.')
                    );
                    return;
                }
            }

            dialog.hide();

            update_mission(frm, {
                action: include_schedule
                    ? 'Reassign and Reschedule'
                    : 'Replace Technician',
                old_technician: values.old_technician,
                new_technician: values.new_technician,
                assigned_vehicle: values.assigned_vehicle || null,
                planned_start: values.planned_start,
                planned_end: values.planned_end,
                reason: values.reason
            });
        }
    });

    dialog.show();

    let old_field = dialog.fields_dict.old_technician;
    let vehicle_field = dialog.fields_dict.assigned_vehicle;

    function load_current_vehicle() {
        let current_tech = old_field.get_value();
        vehicle_field.set_value(
            get_vehicle_for_technician(frm, current_tech)
        );
    }

    old_field.df.onchange = load_current_vehicle;

    if (assigned.length) {
        old_field.set_value(assigned[0]);
        load_current_vehicle();
    }
}

function open_add_technician_dialog(frm) {
    frappe.prompt(
        [
            {
                label: __('New Technician'),
                fieldname: 'new_technician',
                fieldtype: 'Link',
                options: 'User',
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            enabled: 1
                        }
                    };
                }
            },
            {
                label: __('Assigned Vehicle'),
                fieldname: 'assigned_vehicle',
                fieldtype: 'Link',
                options: 'Vehicle'
            },
            {
                label: __('Reason'),
                fieldname: 'reason',
                fieldtype: 'Small Text',
                reqd: 1
            }
        ],
        function(values) {
            if (
                !validate_vehicle_choice(
