                fieldtype: 'Select',
                options: assigned.join('\n'),
                reqd: 1
            },
            {
                label: __('Reason'),
                fieldname: 'reason',
                fieldtype: 'Small Text',
                reqd: 1
            }
        ],
        function(values) {
            update_mission(frm, {
                action: 'Remove Technician',
                old_technician: values.old_technician,
                reason: values.reason
            });
        },
        __('Remove Technician'),
        __('Remove')
    );
}

function open_change_vehicle_dialog(frm) {
    let assigned = get_assigned_technicians(frm);

    if (!assigned.length) {
        frappe.msgprint(
            __('No technician is currently assigned to this mission.')
        );
        return;
    }

    let dialog = new frappe.ui.Dialog({
        title: __('Change Vehicle Assignment'),
        fields: [
            {
                label: __('Technician'),
                fieldname: 'old_technician',
                fieldtype: 'Select',
                options: assigned.join('\n'),
                reqd: 1
            },
            {
                label: __('Current Vehicle'),
                fieldname: 'current_vehicle',
                fieldtype: 'Link',
                options: 'Vehicle',
                read_only: 1
            },
            {
                label: __('New Assigned Vehicle'),
                fieldname: 'assigned_vehicle',
                fieldtype: 'Link',
                options: 'Vehicle'
            },
            {
                label: __('Reason'),
                fieldname: 'reason',
                fieldtype: 'Small Text',
                reqd: 1
            }
        ],
        primary_action_label: __('Change Vehicle'),
        primary_action: function(values) {
            if (
                !validate_vehicle_choice(
                    frm,
                    values.old_technician,
                    values.assigned_vehicle
                )
            ) {
                return;
            }

            dialog.hide();

            update_mission(frm, {
                action: 'Change Vehicle',
                old_technician: values.old_technician,
                assigned_vehicle: values.assigned_vehicle || null,
                reason: values.reason
            });
        }
    });

    dialog.show();

    let tech_field = dialog.fields_dict.old_technician;
    let current_field = dialog.fields_dict.current_vehicle;
    let new_field = dialog.fields_dict.assigned_vehicle;

    function load_vehicle() {
        let tech = tech_field.get_value();
        let vehicle = get_vehicle_for_technician(frm, tech);

        current_field.set_value(vehicle);
        new_field.set_value(vehicle);
    }

    tech_field.df.onchange = load_vehicle;

    if (assigned.length) {
        tech_field.set_value(assigned[0]);
        load_vehicle();
    }
