function open_reschedule_dialog(frm) {
    let fields = get_schedule_fields(frm);

    fields.push({
        label: __('Reason'),
        fieldname: 'reason',
        fieldtype: 'Small Text',
        reqd: 1
    });

    frappe.prompt(
        fields,
        function(values) {
            let start = moment(values.planned_start);
            let end = moment(values.planned_end);

            if (!end.isAfter(start)) {
                frappe.msgprint(
                    __('Planned End must be after Planned Start.')
                );
                return;
            }

            update_mission(frm, {
                action: 'Reschedule Mission',
                planned_start: values.planned_start,
                planned_end: values.planned_end,
                reason: values.reason
            });
        },
        __('Reschedule Mission'),
        __('Reschedule')
    );
}

function update_mission(frm, values) {
    frappe.call({
        method:
            'maintenance_app.api.update_tech_mission_assignment_and_schedule',
        args: {
            mission_name: frm.doc.name,
            action: values.action,
            reason: values.reason,
            old_technician: values.old_technician || null,
            new_technician: values.new_technician || null,
            planned_start: values.planned_start || null,
            planned_end: values.planned_end || null,
            assigned_vehicle:
                values.assigned_vehicle !== undefined
                    ? values.assigned_vehicle
                    : null
        },
        freeze: true,
        freeze_message: __('Updating Tech Mission...'),
        callback: function(r) {
            if (!r.message || !r.message.ok) return;

            frappe.show_alert({
                message: __('Tech Mission and Service Ticket updated successfully.'),
                indicator: 'green'
            });

            frm.reload_doc();
        }
    });
}

function create_intervention(frm) {
