            frm.reload_doc().then(function() {
                frappe.set_route(
                    'Form',
                    'Mission Intervention',
                    r.message.intervention
                );
            });
        }
    });
}

function create_additional_mi(frm) {
    let dialog = new frappe.ui.Dialog({
        title: __('Additional Equipment Found'),
        fields: [
            {
                label: __('Equipment'),
                fieldname: 'asset',
                fieldtype: 'Link',
                options: 'Installed Equipment',
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            custom_parent_customer:
                                frm.doc.custom_parent_customer,
                            custom_branch:
                                frm.doc.custom_branch
                        }
                    };
                },
                onchange: function() {
                    dialog.set_value('component_row_id', '');
                    refresh_additional_mi_components();
                }
            },
            {
                label: __('Target'),
                fieldname: 'target_scope',
                fieldtype: 'Select',
                options: ['Equipment', 'Component'].join('\n'),
                default: 'Equipment',
                reqd: 1,
                onchange: function() {
                    refresh_additional_mi_components();
                }
            },
            {
                label: __('Component'),
                fieldname: 'component_row_id',
                fieldtype: 'Select',
                depends_on: 'eval:doc.target_scope=="Component"',
                mandatory_depends_on: 'eval:doc.target_scope=="Component"',
                description: __('Select a currently installed component on the chosen equipment.')
            },
            {
                label: __('Intervention Type'),
                fieldname: 'intervention_type',
                fieldtype: 'Select',
                options: [
                    'Service',
                    'Repair',
                    'Preventive Maintenance',
                    'Inspection'
                ].join('\n'),
                default: 'Service',
                reqd: 1
            },
            {
                label: __('Subject'),
                fieldname: 'subject',
                fieldtype: 'Data'
            },
            {
                label: __('Reason'),
                fieldname: 'reason',
                fieldtype: 'Small Text',
                reqd: 1
            }
        ],
        primary_action_label: __('Create MI'),
        primary_action: function(values) {
            if (
                values.target_scope === 'Component' &&
                !values.component_row_id
            ) {
                frappe.msgprint(__('Please select the component to work on.'));
                return;
            }

            dialog.disable_primary_action();

            frappe.call({
                method:
                    'maintenance_app.api.create_additional_intervention_from_mission',
                args: {
                    mission_name: frm.doc.name,
                    asset_name: values.asset,
                    reason: values.reason,
                    subject: values.subject,
                    intervention_type: values.intervention_type,
                    target_scope: values.target_scope || 'Equipment',
                    component_row_id:
                        values.target_scope === 'Component'
                            ? values.component_row_id
                            : null
                },
                freeze: true,
                freeze_message: __('Creating Additional Intervention...'),
                callback: function(r) {
                    if (!r.message) {
                        dialog.enable_primary_action();
                        return;
                    }

                    dialog.hide();

                    frm.reload_doc().then(function() {
                        frappe.set_route(
                            'Form',
                            'Mission Intervention',
                            r.message.intervention
                        );
                    });
                },
                error: function() {
                    dialog.enable_primary_action();
                }
            });
        }
    });

    function refresh_additional_mi_components() {
        let asset = dialog.get_value('asset');
        let target_scope = dialog.get_value('target_scope');
        let field = dialog.get_field('component_row_id');

        if (!field) return;

        if (target_scope !== 'Component') {
            dialog.set_value('component_row_id', '');
            field.df.options = '';
            field.refresh();
            return;
        }

        if (!asset) {
            dialog.set_value('component_row_id', '');
            field.df.options = '';
            field.refresh();
            return;
        }

        frappe.call({
            method: 'maintenance_app.api.get_additional_mi_components',
            args: {
                equipment_name: asset
            },
            callback: function(r) {
                let rows = r.message || [];
                let options = [''];

                rows.forEach(function(row) {
                    let label = row.display_name || row.equipment_component;
                    if (row.serial) {
                        label += ' | ' + row.serial;
                    }

                    options.push({
                        label: label,
                        value: row.row_id
                    });
                });

                field.df.options = options;
                field.refresh();

                if (!rows.length) {
                    frappe.msgprint(
                        __('No active installed components were found on this equipment.')
                    );
                }
            }
        });
    }

    dialog.show();
}

frappe.ui.form.on('Tech Planning', {
    refresh: function(frm) {
