    if (!frm.doc.custom_planned_team || frm.doc.custom_planned_team.length === 0) {
        frappe.msgprint(__('Please add at least one technician in Planned Team.'));
        return false;
    }

    return true;
}

function toggle_reschedule_fields(frm) {
    let has_mission = !!frm.doc.custom_mission_ref;

    [
        'custom_reschedule_required',
        'custom_reschedule_reason',
        'custom_reschedule_notes',
