/* =========================
   SAFE DUPLICATION
   The generic Frappe Duplicate action copies most field values.
   For a new physical unit, identity-specific fields must be cleared.

   Kept:
   - equipment template / item
   - equipment type, make, model and category
   - customer and branch
   - maintenance settings

   Cleared:
   - physical serial number (custom_asset_id)
   - client asset code
   - generated display name
   - linked warranty and warranty-derived details
   - installed component snapshot
========================= */

const IE_DUPLICATE_SESSION_KEY = 'gotech_ie_duplicate_context';
const IE_DUPLICATE_MAX_AGE_MS = 2 * 60 * 1000;

function install_safe_duplicate_handler(frm) {
    if (frm.__gotech_safe_duplicate_installed) {
        return;
    }

    if (typeof frm.copy_doc !== 'function') {
        return;
    }

    let original_copy_doc = frm.copy_doc.bind(frm);

    frm.copy_doc = function() {
        let context = {
            source_name: frm.doc.name || '',
            created_at: Date.now()
        };

        try {
            window.sessionStorage.setItem(
                IE_DUPLICATE_SESSION_KEY,
                JSON.stringify(context)
            );
        } catch (e) {
            window.__gotech_ie_duplicate_context = context;
        }

        return original_copy_doc();
    };

    frm.__gotech_safe_duplicate_installed = true;
}

function get_ie_duplicate_context() {
    let context = null;

    try {
        let raw = window.sessionStorage.getItem(
            IE_DUPLICATE_SESSION_KEY
        );

        if (raw) {
            context = JSON.parse(raw);
        }
    } catch (e) {
        context = window.__gotech_ie_duplicate_context || null;
    }

    return context;
}

function clear_ie_duplicate_context() {
    try {
        window.sessionStorage.removeItem(
            IE_DUPLICATE_SESSION_KEY
        );
    } catch (e) {
        // Ignore browser storage restrictions.
    }

    window.__gotech_ie_duplicate_context = null;
}

function clear_identity_fields_after_duplicate(frm) {
    if (!frm.is_new() || !frm.doc.__islocal) {
        return;
    }

    let context = get_ie_duplicate_context();

    if (!context || !context.created_at) {
        return;
    }

    let age = Date.now() - Number(context.created_at);

    if (age < 0 || age > IE_DUPLICATE_MAX_AGE_MS) {
        clear_ie_duplicate_context();
        return;
    }

    if (frm.__gotech_duplicate_identity_cleared) {
        return;
    }

    frm.__gotech_duplicate_identity_cleared = true;
    clear_ie_duplicate_context();

    let clear_tasks = [];

    [
        'custom_asset_id',
        'custom_asset_name',
        'custom_client_asset_code',
        'custom_display_name',
        'custom_parent_customer',
        'custom_branch',
        'custom_client_type',
        'custom_region',
        'custom_warranty',
        'custom_warranty_period_years',
        'custom_coverage_type'
    ].forEach(function(fieldname) {
        if (
            frm.fields_dict[fieldname] &&
            frm.doc[fieldname]
        ) {
            clear_tasks.push(
                frm.set_value(fieldname, '')
            );
        }
    });

    // A duplicated physical unit must not inherit the source unit's
    // installed component records.
    if (
        frm.fields_dict.custom_installed_components &&
        (frm.doc.custom_installed_components || []).length
    ) {
        frm.clear_table('custom_installed_components');
        frm.refresh_field('custom_installed_components');
    }

    Promise.all(clear_tasks).then(function() {
        if (frm.fields_dict.custom_asset_status) {
            frm.set_value(
                'custom_asset_status',
                'Pending Installation'
            );
        }

        update_display_name(frm);

        frappe.show_alert({
            message: __(
                'Equipment duplicated. Identity, customer, branch, warranty and installed components were cleared. Status set to Pending Installation.'
            ),
            indicator: 'orange'
        });
    });
}


