function set_main_equipment_item_filter(frm) {
    if (!frm.fields_dict.custom_item_code) return;

    frm.set_query('custom_item_code', function() {
        return {
            filters: {
                disabled: 0,
                is_stock_item: 1
            }
        };
    });
}

function fetch_item_details(frm) {
    if (!frm.doc.custom_item_code) return;

    frappe.db.get_value(
        'Item',
        frm.doc.custom_item_code,
        ['item_name', 'brand', 'item_group'],
        function(r) {
            if (!r) return;

            if (r.brand) frm.set_value('custom_make', r.brand);
            if (r.item_name) frm.set_value('custom_model', r.item_name);
            if (r.item_group) frm.set_value('custom_asset_category', r.item_group);

            if (!frm.doc.custom_asset_name && r.item_name) {
                frm.set_value('custom_asset_name', r.item_name);
            }

            update_display_name(frm);
        }
    );
}


/* =========================
   DISPLAY NAME
========================= */

function update_display_name(frm) {
    let equipment_name = frm.doc.custom_asset_name || '';
    let client_asset_code = frm.doc.custom_client_asset_code || '';
    let serial_number = frm.doc.custom_asset_id || '';

    let display_name = [equipment_name, client_asset_code, serial_number]
        .filter(Boolean)
        .join(' - ');

    if (
        frm.fields_dict.custom_display_name &&
        frm.doc.custom_display_name !== display_name
    ) {
        frm.set_value('custom_display_name', display_name);
    }
}


/* =========================
   CUSTOMER / BRANCH
========================= */

function set_branch_filter(frm) {
    if (!frm.fields_dict.custom_branch) return;

    frm.set_query('custom_branch', function() {
        if (!frm.doc.custom_parent_customer) return {};

        return {
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_parent_customer]
            ]
        };
    });
}

function sync_customer_from_branch(frm) {
    if (frm.doc.custom_branch && !frm.doc.custom_parent_customer) {
        frappe.db.get_value(
            'Client Branch',
            frm.doc.custom_branch,
            'custom_parent_customer',
            function(r) {
                if (r && r.custom_parent_customer) {
                    frm.set_value('custom_parent_customer', r.custom_parent_customer);
                }
            }
        );
    }
}

function validate_branch_customer(frm) {
    if (frm.doc.custom_parent_customer && frm.doc.custom_branch) {
        frappe.db.get_value(
            'Client Branch',
            frm.doc.custom_branch,
            'custom_parent_customer',
            function(r) {
                if (r && r.custom_parent_customer !== frm.doc.custom_parent_customer) {
                    frm.set_value('custom_branch', '');
                    frappe.msgprint(__('Selected branch does not belong to this customer.'));
                }
            }
        );
    }
}

function sync_client_type_from_branch(frm) {
    if (!frm.fields_dict.custom_client_type) {
        return;
    }

    if (!frm.doc.custom_branch) {
        if (frm.doc.custom_client_type) {
            frm.set_value('custom_client_type', '');
        }
        return;
    }

    frappe.db.get_value(
        'Client Branch',
        frm.doc.custom_branch,
        'custom_site_type'
    ).then(function(r) {
        let client_type =
            r.message && r.message.custom_site_type
                ? r.message.custom_site_type
                : '';

        if ((frm.doc.custom_client_type || '') !== client_type) {
            frm.set_value('custom_client_type', client_type);
        }
    });
}


function sync_region_from_branch(frm) {
    if (!frm.fields_dict.custom_region) {
        return;
    }

    if (!frm.doc.custom_branch) {
        if (frm.doc.custom_region) {
            frm.set_value('custom_region', '');
        }
        return;
    }

    frappe.db.get_value(
        'Client Branch',
        frm.doc.custom_branch,
        'custom_region'
    ).then(function(branch_response) {
        let region_id =
            branch_response.message &&
            branch_response.message.custom_region
                ? branch_response.message.custom_region
                : '';

        if (!region_id) {
            if (frm.doc.custom_region) {
                frm.set_value('custom_region', '');
            }
            return;
        }

        frappe.model.with_doctype('Client Branch', function() {
            let region_field = frappe.meta.get_docfield(
                'Client Branch',
                'custom_region'
            );

            let region_doctype =
                region_field && region_field.options
                    ? region_field.options
                    : '';

            if (!region_doctype) {
                frm.set_value('custom_region', region_id);
                return;
            }

            frappe.model.with_doctype(region_doctype, function() {
                let region_meta = frappe.get_meta(region_doctype);

                let title_field =
                    region_meta && region_meta.title_field
                        ? region_meta.title_field
                        : 'name';

                frappe.db.get_value(
                    region_doctype,
                    region_id,
                    title_field
                ).then(function(region_response) {
                    let region_name =
                        region_response.message &&
                        region_response.message[title_field]
                            ? region_response.message[title_field]
                            : region_id;

                    if (frm.doc.custom_region !== region_name) {
                        frm.set_value(
                            'custom_region',
                            region_name
                        );
                    }
                });
            });
        });
    });
}


