/* =========================
   AUTO REFRESH COMPONENT SNAPSHOT
   Equipment Component = source of truth
   Installed Components table = display snapshot
========================= */

function refresh_component_snapshot(frm) {
    let rows = frm.doc.custom_installed_components || [];

    if (!rows.length) {
        return;
    }

    if (frm._refreshing_component_snapshot) {
        return;
    }

    frm._refreshing_component_snapshot = true;

    let promises = [];

    rows.forEach(function(row) {
        if (!row.custom_equipment_component) {
            return;
        }

        let p = frappe.db.get_doc(
            'Equipment Component',
            row.custom_equipment_component
        )
            .then(function(component) {
                let changed = false;

                let serial = component.custom_serial_number || component.custom_serial || '';
                let status = component.custom_status || 'Installed';

                if (status === 'Active') {
                    status = 'Installed';
                }


                if ((row.custom_component_group || '') !== (component.custom_component_group || '')) {
                    row.custom_component_group = component.custom_component_group || '';
                    changed = true;
                }

                if ((row.custom_equipment_type || '') !== (component.custom_equipment_type || '')) {
                    row.custom_equipment_type = component.custom_equipment_type || '';
                    changed = true;
                }

                if ((row.custom_brand || '') !== (component.custom_make || '')) {
                    row.custom_brand = component.custom_make || '';
                    changed = true;
                }

                if ((row.custom_model || '') !== (component.custom_model || '')) {
                    row.custom_model = component.custom_model || '';
                    changed = true;
                }

                if ((row.custom_serial_number || '') !== serial) {
                    row.custom_serial_number = serial;
                    changed = true;
                }

                if ((row.custom_status || '') !== status) {
                    row.custom_status = status;
                    changed = true;
                }

                return changed;
            });

        promises.push(p);
    });

    Promise.all(promises).then(function(results) {
        let has_changes = results.some(function(x) {
            return x === true;
        });

        if (!has_changes) {
            frm._refreshing_component_snapshot = false;
            return;
        }

        frm.refresh_field('custom_installed_components');
        frm.dirty();

        frm.save().then(function() {
            frappe.show_alert({
                message: __('Component details refreshed and saved from component master.'),
                indicator: 'green'
            });

            frm._refreshing_component_snapshot = false;
        }).catch(function() {
            frm._refreshing_component_snapshot = false;

            frappe.msgprint({
                title: __('Component Refresh'),
                indicator: 'red',
                message: __('Component details were refreshed, but the Installed Equipment document could not be saved.')
            });
        });

    }).catch(function() {
        frm._refreshing_component_snapshot = false;
    });
}


/* =========================
   WARRANTY
========================= */

function populate_warranty_details(frm) {
    if (!frm.doc.custom_warranty) {
        return;
    }

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Warranty',
            name: frm.doc.custom_warranty
        },
        callback: function(r) {
            if (!r.message) {
                frappe.msgprint(__('Could not fetch warranty details'));
                return;
            }

            let warranty = r.message;

            if (warranty.custom_warranty_period_years) {
                frm.set_value('custom_warranty_period_years', warranty.custom_warranty_period_years);
            }

            if (warranty.custom_coverage_type) {
                frm.set_value('custom_coverage_type', warranty.custom_coverage_type);
            }

            if (warranty.custom_warranty_title) {
                frappe.show_alert({
                    message: `✓ Warranty linked: ${warranty.custom_warranty_title}`,
                    indicator: 'green'
                });
            }
        }
    });
}

function display_combined_ie_status_banner(frm) {
    if (frm.is_new() || !frm.doc.name) {
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Warranty',
            filters: {
                custom_installed_equipment: frm.doc.name,
                custom_warranty_status: 'Active'
            },
            fields: [
                'name',
                'custom_warranty_title',
                'custom_warranty_end_date',
                'custom_coverage_type'
            ],
            order_by: 'custom_warranty_end_date asc',
            limit_page_length: 0
        },
        callback: function(r) {
            let warranties = r.message || [];
            let warranty_html = '';
            let banner_color = 'blue';

            if (warranties.length > 0) {
                let today = frappe.datetime.get_today();

                let active_warranties = warranties.filter(function(w) {
                    return w.custom_warranty_end_date && w.custom_warranty_end_date >= today;
                });

                if (active_warranties.length > 0) {
                    let earliest = active_warranties[0];

                    let end_parts = earliest.custom_warranty_end_date.split('-');
                    let today_parts = today.split('-');

                    let end_date = new Date(end_parts[0], end_parts[1] - 1, end_parts[2]);
                    let today_date = new Date(today_parts[0], today_parts[1] - 1, today_parts[2]);

                    let days_remaining = Math.ceil((end_date - today_date) / (1000 * 60 * 60 * 24));

                    if (days_remaining < 7) {
                        banner_color = 'red';
                    } else if (days_remaining < 30) {
                        banner_color = 'orange';
                    } else {
                        banner_color = 'green';
                    }

                    let warranty_count = active_warranties.length;
                    let count_text = warranty_count > 1 ? `${warranty_count} active warranties` : '1 active warranty';

                    warranty_html = `
                        <span style="color: inherit; font-weight: bold;">WARRANTY:</span>
                        ${count_text} - ${earliest.custom_coverage_type || ''} -
                        Expires in ${days_remaining} days (${earliest.custom_warranty_end_date})
                    `;
                } else {
                    banner_color = 'red';
                    warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> All warranties expired';
                }
            } else {
                warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> No active warranty';
            }

            let headline = `
                <div style="line-height: 1.6;">
                    <div>
                        <span style="color: inherit; font-weight: bold;">OPERATIONAL:</span>
                        Fields locked. Use interventions for operational changes.
                    </div>
                    <div style="margin-top: 8px; border-top: 1px solid rgba(0,0,0,0.1); padding-top: 8px;">
                        ${warranty_html}
                    </div>
                </div>
            `;

            frm.dashboard.set_headline(headline, banner_color);
        }
    });
}


