function prepare_ie_ticket_dialog(dialog, frm, is_component) {
    let request_field = dialog.get_field('request_type');

    if (request_field && request_field.$input) {
        request_field.$input.on('change', function() {
            update_ie_ticket_type_options(dialog);
        });
    }

    update_ie_ticket_type_options(dialog);
}

function update_ie_ticket_type_options(dialog) {
    let request_type = dialog.get_value('request_type') || 'Breakdown';
    let options = IE_TICKET_TYPES[request_type] || [];
    let ticket_type_field = dialog.get_field('ticket_type');

    if (!ticket_type_field) {
        return;
    }

    ticket_type_field.df.options = options.join('\n');
    ticket_type_field.refresh();

    let current = dialog.get_value('ticket_type');

    if (!options.includes(current)) {
        dialog.set_value('ticket_type', options[0] || '');
    }
}

function create_ticket_from_ie(frm, values, component_name, dialog) {
    let technicians = values.technicians || [];

    if (typeof technicians === 'string') {
        technicians = technicians
            .split(',')
            .map(function(value) {
                return value.trim();
            })
            .filter(Boolean);
    }

    if (!technicians.length) {
        frappe.msgprint(__('Please select at least one technician.'));
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.create_ticket_from_installed_equipment',
        args: {
            equipment_name: frm.doc.name,
            component_name: component_name || null,
            subject: values.subject,
            description: values.description,
            request_type: values.request_type,
            ticket_type: values.ticket_type,
            priority: values.priority,
            technicians: JSON.stringify(technicians),
            work_type: values.work_type
        },
        freeze: true,
        freeze_message: __('Creating Service Ticket...'),
        callback: function(r) {
            if (!r.message || !r.message.ticket) {
                return;
            }

            dialog.hide();

            frappe.show_alert({
                message: __('Service Ticket created successfully.'),
                indicator: 'green'
            });

            frappe.set_route(
                'Form',
                'Service Ticket',
                r.message.ticket
            );
        }
    });
}

