function apply_ticket_type_filter(frm, clear_invalid) {
    if (!frm.fields_dict.custom_ticket_type) {
        return;
    }

    let request_type = frm.doc.custom_request_type || "";
    let allowed = TICKET_TYPE_BY_REQUEST_TYPE[request_type] || ALL_TICKET_TYPES;

    frm.set_df_property(
        "custom_ticket_type",
        "options",
        allowed.join("\n")
    );

    frm.refresh_field("custom_ticket_type");

    if (
        clear_invalid &&
        frm.doc.custom_ticket_type &&
        !allowed.includes(frm.doc.custom_ticket_type)
    ) {
        frm.set_value("custom_ticket_type", "");
        frappe.show_alert({
            message: __("Ticket Type cleared because it is not valid for the selected Request Type."),
            indicator: "orange"
        });
    }
}


