function clear_ticket_contacts(frm) {
    frm.clear_table('custom_branch_contacts');
    frm.clear_table('custom_head_office_contacts');

    frm.refresh_fields([
        'custom_branch_contacts',
        'custom_head_office_contacts'
    ]);
}

function load_ticket_contacts(frm) {
    clear_ticket_contacts(frm);

    if (!frm.doc.custom_client_branch) return;

    frappe.db.get_doc('Client Branch', frm.doc.custom_client_branch)
        .then(branch => {
            (branch.custom_branch_contacts || []).forEach(row => {
                let child = frm.add_child('custom_branch_contacts');

                child.custom_contact = row.custom_contact || '';
                child.custom_contact_role = row.custom_contact_role || '';
                child.custom_phone = row.custom_phone || '';
                child.custom_email = row.custom_email || '';
            });

            (branch.custom_head_office_contacts || []).forEach(row => {
                let child = frm.add_child('custom_head_office_contacts');

                child.custom_contact = row.custom_contact || '';
                child.custom_contact_role = row.custom_contact_role || '';
                child.custom_phone = row.custom_phone || '';
                child.custom_email = row.custom_email || '';
            });

            frm.refresh_fields([
                'custom_branch_contacts',
                'custom_head_office_contacts'
            ]);
        });
}

function load_applicant_details(frm) {
    if (!frm.doc.custom_applicant) {
        frm.set_value('custom_applicant_role', '');
        frm.set_value('custom_applicant_email', '');
        frm.set_value('custom_applicant_phone', '');
        return;
    }

    frappe.db.get_doc('Contact', frm.doc.custom_applicant).then(contact => {
        frm.set_value('custom_applicant_role', contact.designation || '');

        let email = '';
        let phone = '';

        if (contact.email_ids && contact.email_ids.length) {
            let primary_email = contact.email_ids.find(e => e.is_primary);
            email = primary_email ? primary_email.email_id : contact.email_ids[0].email_id;
        }

        if (contact.phone_nos && contact.phone_nos.length) {
            let primary_phone = contact.phone_nos.find(p => p.is_primary_mobile_no || p.is_primary_phone);
            phone = primary_phone ? primary_phone.phone : contact.phone_nos[0].phone;
        }

        frm.set_value('custom_applicant_email', email || '');
        frm.set_value('custom_applicant_phone', phone || '');
    });
}

