        },
        callback: function(r) {
            if (!r.message) return;

            let planning_name = r.message.name;

            copy_planned_team_to_doc(frm, 'Tech Planning', planning_name, function() {
                copy_ticket_details_to_doc(frm, 'Tech Planning', planning_name, function() {
                    frm.set_value('custom_primary_planning_ref', planning_name);
                    frm.set_value('custom_planning_required', 1);
                    frm.set_value('custom_planning_status', 'Required');
                    frm.set_value('custom_ticket_status', 'Ready for Planning');

                    frm.save().then(() => {
                        frappe.set_route('Form', 'Tech Planning', planning_name);
                    });
                });
