function get_mission_team_dialog_data(frm) {
    return (frm.doc.custom_planned_team || [])
        .filter(row => !!row.custom_technician)
        .map(row => ({
            custom_technician: row.custom_technician,
            custom_assigned_vehicle: row.custom_assigned_vehicle || ''
        }));
}

function get_common_assigned_vehicle(team_rows) {
    let vehicles = [];

    (team_rows || []).forEach(function(row) {
        let vehicle = row.custom_assigned_vehicle || '';

        if (vehicle && !vehicles.includes(vehicle)) {
            vehicles.push(vehicle);
        }
    });

    // Legacy/summary value only. If several company vehicles are used,
    // the parent vehicle field is deliberately left blank.
    return vehicles.length === 1 ? vehicles[0] : '';
}

function validate_mission_team_assignments(frm, team_rows) {
    if (!team_rows || !team_rows.length) {
        frappe.msgprint(
            __('Please assign at least one technician in Planned Team.')
        );
        return false;
    }

    let seen_technicians = {};
    let duplicates = [];

    team_rows.forEach(function(row) {
        let technician = row.custom_technician || '';

        if (!technician) {
            return;
        }

        if (seen_technicians[technician]) {
            duplicates.push(technician);
        }

        seen_technicians[technician] = true;
    });

    if (duplicates.length) {
        frappe.msgprint(
            __('The same technician appears more than once in Planned Team: {0}', [
                [...new Set(duplicates)].join(', ')
            ])
        );
        return false;
    }

    /*
     * For normal company transport, each technician must have an Assigned
     * Vehicle. The same vehicle may be selected for several technicians.
     *
     * If Service Ticket.custom_external_vehicle is filled, internal Vehicle
     * links may be left blank because transport is external/hired.
     */
    if (!frm.doc.custom_external_vehicle) {
        let missing_vehicle = team_rows
            .filter(
                row =>
                    row.custom_technician &&
                    !row.custom_assigned_vehicle
            )
            .map(row => row.custom_technician);

        if (missing_vehicle.length) {
            frappe.msgprint(
                __('Please assign a vehicle to: {0}', [
                    missing_vehicle.join(', ')
                ])
            );
            return false;
        }
    }

    return true;
}

function apply_mission_team_assignments_to_ticket(frm, team_rows) {
    let by_technician = {};

    (team_rows || []).forEach(function(row) {
        if (!row.custom_technician) {
            return;
        }

        by_technician[row.custom_technician] =
            row.custom_assigned_vehicle || '';
    });

    let updates = [];

    (frm.doc.custom_planned_team || []).forEach(function(row) {
        if (
            !row.custom_technician ||
            !Object.prototype.hasOwnProperty.call(
                by_technician,
                row.custom_technician
            )
        ) {
            return;
        }

        updates.push(
            frappe.model.set_value(
                row.doctype,
                row.name,
                'custom_assigned_vehicle',
                by_technician[row.custom_technician]
            )
        );
    });

    return Promise.all(updates).then(function() {
        frm.refresh_field('custom_planned_team');
    });
}

function prompt_and_create_tech_mission(frm, planning_name) {
    if (!validate_ticket_ready(frm)) return;

    let team_data = get_mission_team_dialog_data(frm);

    if (!team_data.length) {
        frappe.msgprint(
            __('Please assign at least one technician in Planned Team before creating a mission.')
        );
        return;
    }

    let dialog = new frappe.ui.Dialog({
        title: __('Plan Mission'),
        size: 'large',
        fields: [
            {
                label: __('Planned Start'),
                fieldname: 'planned_start',
                fieldtype: 'Datetime',
                reqd: 1
            },
            {
                label: __('Planned End'),
                fieldname: 'planned_end',
                fieldtype: 'Datetime',
                reqd: 1
            },
            {
                fieldtype: 'Section Break',
                label: __('Technician / Vehicle Assignment')
            },
            {
                fieldname: 'team_assignments',
                fieldtype: 'Table',
                label: __('Planned Team'),
                cannot_add_rows: true,
                cannot_delete_rows: true,
                in_place_edit: true,
                data: team_data,
                fields: [
                    {
                        label: __('Technician'),
                        fieldname: 'custom_technician',
                        fieldtype: 'Link',
                        options: 'User',
                        in_list_view: 1,
                        read_only: 1,
                        columns: 5
                    },
                    {
                        label: __('Assigned Vehicle'),
                        fieldname: 'custom_assigned_vehicle',
                        fieldtype: 'Link',
                        options: 'Vehicle',
                        in_list_view: 1,
                        columns: 5
                    }
                ]
            },
            {
                fieldtype: 'HTML',
                fieldname: 'vehicle_assignment_help',
                options:
                    '<div class="text-muted small">' +
                    __('The same company vehicle may be assigned to more than one technician travelling together.') +
                    '</div>'
            }
        ],
        primary_action_label: __('Create Mission'),
        primary_action: function(values) {
            let start_dt = moment(values.planned_start);
            let end_dt = moment(values.planned_end);

            if (!end_dt.isAfter(start_dt)) {
                frappe.msgprint(
                    __('Planned End must be after Planned Start.')
                );
                return;
            }

            let team_rows =
                dialog.fields_dict.team_assignments.grid
                    .get_data()
                    .filter(row => !!row.custom_technician);

            if (!validate_mission_team_assignments(frm, team_rows)) {
                return;
            }

            apply_mission_team_assignments_to_ticket(
                frm,
                team_rows
            )
                .then(function() {
                    return frm.save();
                })
                .then(function() {
                    dialog.hide();

                    create_tech_mission(
                        frm,
                        planning_name,
                        values.planned_start,
                        values.planned_end
                    );
                })
                .catch(function(error) {
                    console.error(
                        'Could not save technician / vehicle assignments:',
                        error
                    );

                    frappe.msgprint(
                        __('Could not save the technician / vehicle assignments. Please try again.')
                    );
                });
        }
    });

    dialog.show();
}

function create_tech_mission(
    frm,
    planning_name,
    planned_start,
    planned_end
) {
    if (!validate_ticket_ready(frm)) return;

    let common_vehicle = get_common_assigned_vehicle(
        frm.doc.custom_planned_team || []
    );

    let mission_doc = {
        doctype: 'Tech Mission',
        custom_subject: frm.doc.custom_subject || '',
        custom_service_ticket: frm.doc.name,
        custom_tech_planning: planning_name || '',
        custom_company: frm.doc.custom_company || '',
        custom_parent_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_asset: frm.doc.custom_target_equipment,
        custom_target_component_name: frm.doc.custom_target_component_name || '',
        custom_parent_equipment: frm.doc.custom_parent_equipment || '',

        custom_component_group: frm.doc.custom_component_group || '',
        custom_component_item: frm.doc.custom_component_item || '',
        custom_component_row_id: frm.doc.custom_component_row_id || '',
        custom_component_serial: frm.doc.custom_component_serial || '',
        custom_component_brand: frm.doc.custom_component_brand || '',
        custom_component_model: frm.doc.custom_component_model || '',
        custom_ticket_type: frm.doc.custom_ticket_type || 'Service',
        custom_work_type: frm.doc.custom_work_type || 'Quick Intervention',
        custom_service_type: frm.doc.custom_service_type || 'Billable',
        custom_priority: frm.doc.custom_priority || '',
        custom_response_due: frm.doc.custom_response_due || '',
        custom_resolution_due: frm.doc.custom_resolution_due || '',
        custom_mission_status: 'Scheduled',
        custom_planned_starttime: planned_start || '',
        custom_planned_endtime: planned_end || '',

        // Legacy/summary field only. The real assignment is on Planned Team.
        custom_vehicle: common_vehicle || '',

        custom_request_description: build_request_description(frm),
        custom_applicant: frm.doc.custom_applicant || '',
        custom_applicant_role: frm.doc.custom_applicant_role || '',
        custom_applicant_email: frm.doc.custom_applicant_email || '',
        custom_applicant_phone: frm.doc.custom_applicant_phone || ''
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: {
            doc: mission_doc
        },
        callback: function(r) {
            if (!r.message) return;

            let mission_name = r.message.name;

            copy_planned_team_to_doc(
                frm,
                'Tech Mission',
                mission_name,
                function() {
                    copy_ticket_details_to_doc(
                        frm,
                        'Tech Mission',
                        mission_name,
                        function() {
                            frm.set_value(
                                'custom_primary_mission_ref',
                                mission_name
                            );
                            frm.set_value(
                                'custom_ticket_status',
                                'Planned'
                            );

                            let planned_technicians = [];

                            (
                                frm.doc.custom_planned_team || []
                            ).forEach(function(row) {
                                if (
                                    row.custom_technician &&
                                    !planned_technicians.includes(
                                        row.custom_technician
                                    )
                                ) {
                                    planned_technicians.push(
                                        row.custom_technician
                                    );
                                }
                            });

                            if (
                                frm.fields_dict.custom_planned_starttime
                            ) {
                                frm.set_value(
                                    'custom_planned_starttime',
                                    planned_start || ''
                                );
                            }

                            if (
                                frm.fields_dict.custom_planned_endtime
                            ) {
                                frm.set_value(
                                    'custom_planned_endtime',
                                    planned_end || ''
                                );
                            }

                            /*
                             * Backward-compatible summary only:
                             * if one common internal vehicle is used, show it.
                             * With multiple vehicles this stays blank.
                             */
                            if (
                                frm.fields_dict.custom_planned_vehicle
                            ) {
                                frm.set_value(
                                    'custom_planned_vehicle',
                                    common_vehicle || ''
                                );
                            }

                            if (
                                frm.fields_dict.custom_planned_technicians
                            ) {
                                frm.set_value(
                                    'custom_planned_technicians',
                                    planned_technicians.join(', ')
                                );
                            }

                            if (planning_name) {
                                frm.set_value(
                                    'custom_primary_planning_ref',
                                    planning_name
                                );
                                frm.set_value(
                                    'custom_planning_status',
                                    'Fully Planned'
                                );
                            } else {
                                frm.set_value(
                                    'custom_planning_required',
                                    0
                                );
                                frm.set_value(
                                    'custom_planning_status',
                                    'Not Required'
                                );
                            }

                            frappe.call({
                                method:
                                    'maintenance_app.api.create_todos_for_existing_mission',
                                args: {
                                    mission_name: mission_name
                                },
                                callback: function() {
                                    append_tech_mission_to_ticket(
                                        frm,
                                        mission_name,
                                        r.message
                                    );

                                    frm.save().then(() => {
                                        frappe.set_route(
                                            'Form',
                                            'Tech Mission',
                                            mission_name
                                        );
                                    });
                                }
                            });
                        }
                    );
                }
            );
        }
    });
}
function create_remote_session(frm) {

    if (!validate_ticket_ready(frm)) return;

    let remote_doc = {
        doctype: "Remote Session",

        custom_service_ticket: frm.doc.name,
        custom_company: frm.doc.custom_company || '',
        custom_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_equipment: frm.doc.custom_target_equipment,

        custom_component: frm.doc.custom_target_component_name || "",

        custom_session_title: frm.doc.custom_subject || "",

        custom_ticket_type: frm.doc.custom_ticket_type || "",

        custom_service_type: frm.doc.custom_service_type || "",

        custom_status: "Draft"
    };

    frappe.call({
        method: "frappe.client.insert",
        args: {
            doc: remote_doc
        },
        callback: function(r) {

            if (!r.message) return;

            let session_name = r.message.name;

            frm.set_value("custom_handling_mode", "Remote");
            frm.set_value("custom_primary_remote_session_ref", session_name);

            frm.save().then(() => {

                frappe.set_route(
                    "Form",
                    "Remote Session",
                    session_name
                );

            });

        }
    });

}

function append_tech_mission_to_ticket(frm, mission_name, mission_doc) {
    if (!frm.fields_dict.custom_tech_missions) {
        return;
    }

    let exists = false;

    (frm.doc.custom_tech_missions || []).forEach(row => {
        if (row.custom_tech_mission === mission_name) {
            exists = true;
        }
    });

    if (exists) {
        return;
    }

    let mission_no = (frm.doc.custom_tech_missions || []).length + 1;

    let technicians = [];

    (frm.doc.custom_planned_team || []).forEach(row => {
        if (row.custom_technician) {
            technicians.push(row.custom_technician);
        }
    });

    let child = frm.add_child('custom_tech_missions');

    child.custom_mission_number = mission_no;
    child.custom_tech_mission = mission_name;
    child.custom_mission_status = mission_doc.custom_mission_status || 'Scheduled';
    child.custom_planned_starttime = mission_doc.custom_planned_starttime || '';
    child.custom_planned_endtime = mission_doc.custom_planned_endtime || '';
    child.custom_assigned_technicians = technicians.join(', ');

    frm.refresh_field('custom_tech_missions');
}

