}

/* ═══════════════════════════════════════════════════════════
   BANNER & STATUS
═══════════════════════════════════════════════════════════ */

function update_mc_banner(frm) {
    let status = frm.doc.custom_status || 'Draft';
    let days_remaining = frm.doc.custom_days_remaining || 0;

    let indicator = 'gray';
    let message = '';

    if (status === 'Draft') {
        indicator = 'gray';
        message = 'Contract Draft - Not Yet Active';
    } else if (status === 'Active') {
        if (days_remaining < 0) {
            indicator = 'red';
            message = '🔴 Contract Expired';
        } else if (days_remaining < 30) {
            indicator = 'orange';
            message = `⚠️ Contract expires in ${days_remaining} days`;
        } else {
            indicator = 'green';
            message = `✓ Active - ${days_remaining} days remaining`;
        }
    } else if (status === 'Expired') {
        indicator = 'red';
        message = '🔴 Contract Expired';
    } else if (status === 'Terminated') {
        indicator = 'red';
        message = '🔴 Contract Terminated';
    }

    frm.page.set_indicator(__(status), indicator);
}

frappe.ui.form.on('Client Branch', {
    setup: function(frm) {
        set_client_branch_contact_filters(frm);
        set_region_filter(frm);
    },

    refresh: function(frm) {

        set_client_branch_contact_filters(frm);
        set_region_filter(frm);

        if (!frm.is_new()) {
            refresh_branch_inventory(frm);
        }

        add_create_service_ticket_button(frm);
        add_plan_intervention_button(frm);
        add_get_directions_button(frm);
    },

    custom_region_type: function(frm) {

        // Clear the previously selected region when the type changes.
        if (frm.doc.custom_region) {
            frm.set_value('custom_region', '');
        }

        set_region_filter(frm);
    },

    custom_region: function(frm) {
        validate_selected_region(frm);
    }
});


/* =========================
   REGION FILTER
========================= */

function set_region_filter(frm) {

    frm.set_query('custom_region', function() {

        let filters = {};

        if (frm.doc.custom_region_type) {
            filters.custom_region_type =
                frm.doc.custom_region_type;
        }

        return {
            filters: filters
        };
    });
}


function validate_selected_region(frm) {

    if (!frm.doc.custom_region) {
        return;
    }

    frappe.db.get_value(
        'Region',
        frm.doc.custom_region,
        [
            'custom_region_type',
            'custom_region_name'
        ]
    ).then(function(r) {

        let region = r.message || {};

        if (
            frm.doc.custom_region_type &&
            region.custom_region_type !==
                frm.doc.custom_region_type
        ) {
            frm.set_value('custom_region', '');

            frappe.msgprint({
                title: __('Invalid Region'),
                indicator: 'orange',
                message: __(
                    'The selected region does not belong to the selected Region Type.'
                )
            });
        }
    });
}


/* =========================
   CONTACT FILTERS
========================= */

function set_client_branch_contact_filters(frm) {

    frm.set_query(
        'custom_contact',
        'custom_branch_contacts',
        function() {
            return {
                filters: [
                    [
                        'Contact',
                        'custom_contact_scope',
                        '=',
                        'Branch Level'
                    ],
                    [
                        'Contact',
                        'custom_client_branch',
                        '=',
                        frm.doc.name
                    ],
                    [
                        'Dynamic Link',
                        'link_doctype',
                        '=',
                        'Customer'
                    ],
                    [
                        'Dynamic Link',
                        'link_name',
                        '=',
                        frm.doc.custom_parent_customer
                    ]
                ]
            };
        }
    );

    frm.set_query(
        'custom_contact',
        'custom_head_office_contacts',
        function() {
            return {
                filters: [
                    [
                        'Contact',
                        'custom_contact_scope',
                        '=',
                        'Head Office Level'
                    ],
                    [
                        'Dynamic Link',
                        'link_doctype',
                        '=',
                        'Customer'
                    ],
                    [
                        'Dynamic Link',
                        'link_name',
                        '=',
                        frm.doc.custom_parent_customer
                    ]
                ]
            };
        }
    );
}


frappe.ui.form.on('Client Branch Contact', {
    custom_contact: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.custom_contact) {
            return;
        }

        frappe.db.get_doc(
            'Contact',
            row.custom_contact
        ).then(function(contact) {

            let primary_email = '';
            let primary_phone = '';

            // =========================
            // EMAIL
            // =========================

            if (
                contact.email_ids &&
                contact.email_ids.length > 0
            ) {

                let primary_email_row =
                    contact.email_ids.find(function(e) {
                        return e.is_primary === 1;
                    });

                if (primary_email_row) {
                    primary_email =
                        primary_email_row.email_id;
                }
                else {
                    primary_email =
                        contact.email_ids[0].email_id;
                }
            }

            // =========================
            // PHONE
            // =========================

            if (
                contact.phone_nos &&
                contact.phone_nos.length > 0
            ) {

                let primary_phone_row =
                    contact.phone_nos.find(function(p) {
                        return (
                            p.is_primary_mobile === 1 ||
                            p.is_primary_phone === 1
                        );
                    });

                if (primary_phone_row) {
                    primary_phone =
                        primary_phone_row.phone;
                }
                else {
                    primary_phone =
                        contact.phone_nos[0].phone;
                }
            }

            // =========================
            // UPDATE CHILD TABLE
            // =========================

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_contact_role',
                contact.designation || ''
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_email',
                primary_email || ''
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_phone',
                primary_phone || ''
            );
        });
    }
});


/* =========================
   BRANCH INVENTORY
========================= */

function refresh_branch_inventory(frm) {

    frappe.call({
        method: 'frappe.client.get_list',

        args: {
            doctype: 'Installed Equipment',

            filters: {
                custom_branch: frm.doc.name
            },

            fields: [
                'name',
                'custom_asset_id',
                'custom_client_asset_code',
                'custom_display_name',
                'custom_model',
                'custom_make',
                'custom_asset_category',
                'custom_asset_status'
            ],

            limit_page_length: 500
        },

        callback: function(r) {

            frm.clear_table(
                'custom_branch_inventory'
            );

            (r.message || []).forEach(
                function(asset) {

                    let row = frm.add_child(
                        'custom_branch_inventory'
                    );

                    row.custom_asset_id =
                        asset.name;

                    row.custom_serial_number =
                        asset.custom_asset_id;

                    row.custom_model =
                        asset.custom_model;

                    row.custom_make =
                        asset.custom_make;

                    row.custom_category =
                        asset.custom_asset_category;

                    row.custom_status =
                        asset.custom_asset_status;

                    if (
                        'custom_client_asset_code' in row
                    ) {
                        row.custom_client_asset_code =
                            asset.custom_client_asset_code;
                    }

                    if (
                        'custom_display_name' in row
                    ) {
                        row.custom_display_name =
                            asset.custom_display_name;
                    }
                }
            );

            frm.refresh_field(
                'custom_branch_inventory'
            );
        }
    });
}


