function add_create_service_ticket_button(frm) {

    if (frm.is_new()) {
        return;
    }

    frm.add_custom_button(
        __('Create Service Ticket'),
        function() {

            let ticket_subject =
                'Service Request: ' +
                (
                    frm.doc.custom_branch ||
                    frm.doc.name
                );

            frappe.call({
                method: 'frappe.client.insert',

                args: {
                    doc: {
                        doctype: 'Service Ticket',

                        custom_subject:
                            ticket_subject,

                        custom_customer:
                            frm.doc.custom_parent_customer,

                        custom_client_branch:
                            frm.doc.name,

                        custom_request_type:
                            'General Request',

                        custom_ticket_status:
                            'Open',

                        custom_client_status:
                            'Submitted'
                    }
                },

                callback: function(r) {

                    if (r && r.message) {

                        frappe.set_route(
                            'Form',
                            'Service Ticket',
                            r.message.name
                        );
                    }
                }
            });
        },

        __('Actions')
    );
}


