   GET DIRECTIONS
========================= */

function add_get_directions_button(frm) {

    if (frm.is_new()) {
        return;
    }

    frm.add_custom_button(
        __('Get Directions'),
        function() {

            if (!frm.doc.custom_address) {

                frappe.msgprint(
                    __('No address found for this branch.')
                );

                return;
            }

            let maps_url =
                'https://www.google.com/maps/search/?api=1&query=' +
                encodeURIComponent(
                    frm.doc.custom_address
                );

            window.open(
                maps_url,
                '_blank'
            );
        },

        __('Actions')
    );
}
